    -- RESPONSIVE SCALE
    --==================================================

    -- Mobile/phone displays use 80% of the normal responsive GUI scale.
    -- Desktop behavior remains exactly at the existing 100% scale.
    local IS_MOBILE_DEVICE = UIS.TouchEnabled and (not UIS.KeyboardEnabled or not UIS.MouseEnabled)
    local MOBILE_GUI_SCALE = 0.80

    local function resize()
        local cam=workspace.CurrentCamera
        if not cam then return end

        local v=cam.ViewportSize
        local baseScale=math.min((v.X-24)/W,(v.Y-24)/H)

        if IS_MOBILE_DEVICE then
            Scale.Scale=math.clamp(baseScale*MOBILE_GUI_SCALE,.45,MOBILE_GUI_SCALE)
        else
            Scale.Scale=math.clamp(baseScale,.55,1)
        end
    end

    resize()
    TrackConnection(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(resize))

    task.defer(function()
        if workspace.CurrentCamera then
            TrackConnection(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(resize))
        end
    end)

