            d.bar.Visible=on
            tw(d.b,{BackgroundTransparency=on and .28 or 1})
            tw(d.t,{TextColor3=on and T.Text or T.White})
            tw(d.icon,{BackgroundColor3=on and T.Red or T.Surface2})
        end
