    local function formatList(items)
        if type(items) ~= "table"
            or #items == 0 then

            return "Select..."
        end

        if #items == 1 then
            return items[1]
        end

        if #items == 2 then
            return items[1]
                .. ", "
                .. items[2]
        end

        return items[1]
            .. ", "
            .. items[2]
            .. " +"
            .. (#items - 2)
    end

