        local index = 1

        for i, value in ipairs(values) do
            if value == initialValue then
                index = i
                break
            end
        end

        local btn = C(N("TextButton", {
            Text =
                tostring(values[index])
                .. "  ▼",

            Font = T.Font,
            TextSize = 11,

            TextColor3 = T.White,
            TextXAlignment = Enum.TextXAlignment.Left,

            BackgroundColor3 = T.Input,
