            end
        end)

        return btn
    end

    local function createToggle(
        parentFrame,
        title,
        subtitle,
        y,
        initial,
        callback
    )
        label(
            parentFrame,
            title,
            UDim2.new(0, 10, 0, y),
            UDim2.new(1, -82, 0, 14),
            11,
            T.White,
            T.Font
