                    0,
                    10,
                    0,
                    y + 14
                ),
                UDim2.new(
                    1,
                    -82,
                    0,
                    13
                ),
                9,
                T.Muted,
                T.Body
            )
        end

        local state =
            initial == true

        local toggle = C(N("TextButton", {
            Text = "",

            BackgroundColor3 =
                state
                and T.Success
                or T.RedDark,

            BorderSizePixel = 0,

            AutoButtonColor = false,

            Position = UDim2.new(
                1,
                -58,
                0,
                y + 2
            ),

            Size = UDim2.fromOffset(
