                23
            )
        }, parentFrame), 12)

        local knob = C(N("Frame", {
            BackgroundColor3 = T.White,
            BorderSizePixel = 0,

            AnchorPoint = Vector2.new(
                0,
                .5
            ),

            Position =
                state
                and UDim2.new(
                    1,
                    -20,
                    .5,
                    0
                )
                or UDim2.new(
                    0,
                    3,
                    .5,
                    0
                ),

            Size = UDim2.fromOffset(
                17,
                17
            )
        }, toggle), 10)

        local api = {}

        function api:Set(value, fireCallback)
            state = value == true

            toggle.BackgroundColor3 =
                state
                and T.Success
                or T.RedDark

            tw(
                knob,
                {
                    Position =
                        state
                        and UDim2.new(
                            1,
                            -20,
                            .5,
                            0
                        )
                        or UDim2.new(
                            0,
                            3,
                            .5,
                            0
                        )
                },
                .15
            )

            if fireCallback ~= false
                and callback then

                callback(state)
            end
        end

        function api:Get()
            return state
        end

        toggle.Activated:Connect(function()
            api:Set(not state)
        end)

        return api
    end

