    local function selectedToList(set)
        local output = {}

        for name, enabled in pairs(set or {}) do
            if enabled then
                table.insert(output, name)
            end
        end

        table.sort(output)

        return output
    end

    local function rebuildPicker()
        for _, child in ipairs(PickerScroll:GetChildren()) do
            if not child:IsA("UIListLayout") then
                child:Destroy()
            end
        end

        local query =
            tostring(PickerSearch.Text or "")
            :lower()

        local rowCount = 0

        for _, name in ipairs(PickerData.Options) do
            if query == ""
                or string.find(
                    string.lower(name),
                    query,
                    1,
                    true
                )
            then
                rowCount += 1

                local selected =
                    PickerData.Selected[name] == true

                local row = C(N("TextButton", {
                    Text = "",

                    BackgroundColor3 =
                        selected
                        and Color3.fromRGB(
                            56,
                            25,
                            32
                        )
                        or T.Surface2,

                    BorderSizePixel = 0,

                    AutoButtonColor = false,

                    Size = UDim2.new(
                        1,
                        -4,
                        0,
                        29
                    ),

                    LayoutOrder = rowCount,

                    ZIndex = 102
                }, PickerScroll), 4)

                local check = label(
                    row,
                    selected and "\u{2713}" or "",
                    UDim2.new(
                        0,
                        8,
                        0,
                        0
                    ),
                    UDim2.fromOffset(
                        18,
                        29
                    ),
                    12,
                    T.Success,
                    T.Font
                )
                check.ZIndex = 103

                local txt = label(
                    row,
                    name,
                    UDim2.new(
                        0,
                        30,
                        0,
                        0
                    ),
                    UDim2.new(
                        1,
                        -38,
                        1,
                        0
                    ),
                    10,
                    T.White,
                    T.Body
                )
                txt.ZIndex = 103

                row.Activated:Connect(function()
                    PickerData.Selected[name] =
                        not PickerData.Selected[name]

                    local enabled =
                        PickerData.Selected[name] == true

                    check.Text =
                        enabled and "\u{2713}" or ""

                    row.BackgroundColor3 =
                        enabled
                        and Color3.fromRGB(
                            56,
                            25,
                            32
                        )
                        or T.Surface2
                end)
            end
        end

        PickerScroll.CanvasSize =
            UDim2.new(
                0,
                0,
                0,
                rowCount * 32
            )
    end

    local function openPicker(
        title,
        options,
        current,
        callback
    )
        PickerTitle.Text = title

        PickerData.Options =
            options or {}

        PickerData.Selected = {}

        for _, value in ipairs(current or {}) do
            PickerData.Selected[value] = true
        end

        PickerData.Callback = callback

        PickerSearch.Text = ""

        rebuildPicker()

        Picker.Visible = true
    end

    PickerSearch
        :GetPropertyChangedSignal("Text")
        :Connect(rebuildPicker)

    PickerSelectAll.Activated:Connect(function()
        for _, name in ipairs(PickerData.Options) do
            PickerData.Selected[name] = true
        end

        rebuildPicker()
    end)

    PickerClear.Activated:Connect(function()
        table.clear(PickerData.Selected)

        rebuildPicker()
    end)

    PickerDone.Activated:Connect(function()
        Picker.Visible = false

        local callback =
            PickerData.Callback

        if callback then
            callback(
                selectedToList(
                    PickerData.Selected
                )
            )
        end
    end)

