        -- V73: Favorite buttons live in their own logical-item layer instead of inside
        -- recycled virtual row Frames. A button is keyed to data.Key for its whole
        -- lifetime, so it can never be temporarily reused by a neighboring row.
        FavoriteRuntime.Buttons = {}
        FavoriteRuntime.ButtonData = {}
        FavoriteRuntime.VisibleKeys = {}
        FavoriteRuntime.NextVisibleKeys = {}

        function FavoriteRuntime.GetButton(data)
            local key = tostring(data and data.Key or "")
            if key == "" then return nil end

            local existing = FavoriteRuntime.Buttons[key]
            if existing and existing.Parent == Scroll then
                return existing
            end

            local button = C(N("TextButton", {
                Name = "InventoryFavoriteAction",
                Text = "FAV",
                Position = UDim2.new(.58, 2, 0, 0),
                Size = UDim2.new(.10, -2, 0, 28),
                BackgroundColor3 = T.Surface3,
                BorderSizePixel = 0,
                TextColor3 = T.White,
                Font = T.Font,
                TextSize = 8,
                AutoButtonColor = false,
                Visible = false,
                ZIndex = 20,
            }, Scroll), 6)
            S(button, T.Line, .58, 1)

            FavoriteRuntime.Buttons[key] = button
            TrackConnection(button.Activated:Connect(function()
                FavoriteRuntime.Toggle(FavoriteRuntime.ButtonData[key])
            end))

            return button
        end

        function FavoriteRuntime.BeginButtonPass()
            table.clear(FavoriteRuntime.NextVisibleKeys)
        end

        function FavoriteRuntime.RenderButton(data, itemIndex)
            local favoriteTotal = tonumber(data and data.FavoriteTotal) or 0
            if favoriteTotal <= 0 then return end

            local key = tostring(data.Key or "")
            local button = FavoriteRuntime.GetButton(data)
            if not button then return end

            FavoriteRuntime.ButtonData[key] = data
            FavoriteRuntime.NextVisibleKeys[key] = true

            -- Anchor to the LOGICAL item's canvas row, not to a pooled Frame.
            local targetY = (itemIndex - 1) * VIRTUAL_ROW_STRIDE + 1
            button.Position = UDim2.new(.58, 2, 0, targetY + 12)

            local favoriteBusy = FavoriteRuntime.Busy[data.Key] == true
            local allFavorite = (tonumber(data.FavoriteCount) or 0) >= favoriteTotal
            button.Active = not favoriteBusy and not State.QueueRunning

            if favoriteBusy then
                button.Text = "..."
                button.BackgroundColor3 = T.Red
            elseif allFavorite then
                button.Text = "UNFAV"
                button.BackgroundColor3 = T.RedDark
            else
                button.Text = "FAV"
                button.BackgroundColor3 = T.Surface3
            end
            button.TextColor3 = T.White
            button.Visible = true
        end

        function FavoriteRuntime.EndButtonPass()
            for key in pairs(FavoriteRuntime.VisibleKeys) do
                if not FavoriteRuntime.NextVisibleKeys[key] then
                    local button = FavoriteRuntime.Buttons[key]
                    if button then
                        button.Visible = false
                        button.Active = false
                    end
                    FavoriteRuntime.VisibleKeys[key] = nil
                end
            end

            for key in pairs(FavoriteRuntime.NextVisibleKeys) do
                FavoriteRuntime.VisibleKeys[key] = true
            end
        end

        function FavoriteRuntime.Prune(rows)
            local keep = {}
            for _, data in ipairs(rows or {}) do
                if (tonumber(data.FavoriteTotal) or 0) > 0 then
                    keep[tostring(data.Key)] = true
                end
            end

            for key, button in pairs(FavoriteRuntime.Buttons) do
                if not keep[key] then
                    if button then pcall(function() button:Destroy() end) end
                    FavoriteRuntime.Buttons[key] = nil
                    FavoriteRuntime.ButtonData[key] = nil
                    FavoriteRuntime.VisibleKeys[key] = nil
                    FavoriteRuntime.NextVisibleKeys[key] = nil
                end
            end
        end

        function FavoriteRuntime.Toggle(data)
            if not data or type(data.FavoriteEntries) ~= "table" or #data.FavoriteEntries == 0 then
                return
            end
            if State.QueueRunning or FavoriteRuntime.Busy[data.Key] then
                return
            end

            local kind = data.FavoriteKind or (data.IsFruit and "Fruit" or "Pet")
            local remote = FavoriteRuntime.Remotes[kind]
            if not remote or type(remote.Fire) ~= "function" then
                setHeaderStatus("FAVORITE ERROR", T.Red)
                Info.Text = "Networking.Backpack.Set" .. tostring(kind) .. "Favorite was not found."
                return
            end

            local rowKey = data.Key
            local displayName = tostring(data.DisplayName or data.Name or kind)
            local targetState = not ((tonumber(data.FavoriteTotal) or 0) > 0
                and (tonumber(data.FavoriteCount) or 0) >= (tonumber(data.FavoriteTotal) or 0))
            local entries = data.FavoriteEntries

            FavoriteRuntime.Busy[rowKey] = true
            if renderVirtualRows then renderVirtualRows() end

            task.spawn(function()
                local changed = 0
                local failed = 0

                for _, entry in ipairs(entries) do
                    if not alive then break end

                    local current = FavoriteRuntime.IsFavorite(entry.Instance)
                    if current ~= targetState then
                        local callOk, response = pcall(function()
                            return remote:Fire(entry.Id, targetState)
                        end)

                        if callOk and response == true then
                            changed += 1
                        else
                            failed += 1
                        end
                        task.wait(0.05)
                    end
                end

                local deadline = os.clock() + 1.5
                while alive and os.clock() < deadline do
                    local ready = true
                    for _, entry in ipairs(entries) do
                        if entry.Instance and entry.Instance.Parent
                            and FavoriteRuntime.IsFavorite(entry.Instance) ~= targetState then
                            ready = false
                            break
                        end
                    end
                    if ready then break end
                    task.wait(0.05)
                end

                FavoriteRuntime.Busy[rowKey] = nil
                if alive then
                    refreshInventory(false)
                    if failed > 0 then
                        setHeaderStatus("FAVORITE PARTIAL", T.Red)
                        Info.Text = displayName .. ": " .. tostring(failed) .. " favorite request(s) failed."
                    else
                        setHeaderStatus(targetState and "FAVORITED" or "UNFAVORITED", T.Success)
                        local noun = kind == "Fruit" and "fruit(s)" or "pet(s)"
                        Info.Text = displayName
                            .. ": "
                            .. tostring(changed)
                            .. (targetState and (" " .. noun .. " favorited.") or (" " .. noun .. " unfavorited."))
                    end
                end
            end)
        end
        setHeaderStatus = function(textValue, color)
            HeaderStatus.Text = tostring(textValue or "")
            HeaderStatus.TextColor3 = color or T.Success
        end

        local function updateInventoryTabs()
            for key, button in pairs(InventoryTabButtons) do
                local active = State.CurrentTab == key
                button.BackgroundTransparency = active and 0 or 1
                button.BackgroundColor3 = active and T.RedDark or T.Surface2
                button.TextColor3 = active and T.White or T.Muted
            end
        end

        local function applyFilters(resetScroll)
            local query = string.lower(trim(State.SearchText))
            local filtered = {}

            for _, item in ipairs(State.LatestItems) do
                local tabMatch = State.CurrentTab == "All"
                    or (State.CurrentTab == "Items" and item.IsFruit ~= true)
                    or (State.CurrentTab == "Fruits" and item.IsFruit == true)

                local searchMatch = query == ""
                    or string.find(string.lower(item.DisplayName or item.Name), query, 1, true)
                    or string.find(string.lower(item.Name), query, 1, true)
                    or string.find(string.lower(item.Category), query, 1, true)
                    or (item.IsFruit and string.find(string.lower(tostring(item.Mutation or "")), query, 1, true))

                if tabMatch and searchMatch then
                    filtered[#filtered + 1] = item
                end
            end

            State.VisibleItems = filtered
            Scroll.CanvasSize = UDim2.new(
                0,
                0,
                0,
                math.max(0, #filtered * VIRTUAL_ROW_STRIDE)
            )

            if resetScroll then
                Scroll.CanvasPosition = Vector2.new(0, 0)
            end

            if renderVirtualRows then
                renderVirtualRows()
            end
        end

        local function updateInfo()
            local totalUnits = 0
            local droppableTypes = 0
            local fruitCount = 0
            local selectedFruitValue = 0

            for _, item in ipairs(State.LatestItems) do
                totalUnits += item.Count
                if item.Droppable then
                    droppableTypes += 1
                end
                if item.IsFruit then
                    fruitCount += 1
                    if State.Selected[item.Key] == true then
                        selectedFruitValue += tonumber(item.Value) or 0
                    end
                end
            end

            -- The Sheckles total is selection-driven: unchecked fruits contribute 0.
            -- This makes the number a live total for the exact fruits queued to drop.
            InventoryTotalValueLabel.Text = "TOTAL  $ " .. inventoryFormatFruitValue(selectedFruitValue)

            if running then
                Info.Text = string.format(
                    "Dropping %s  •  %d/%d confirmed  •  %d attempts",
                    tostring(activeDropDisplayName or activeDropName or "item"),
                    activeDropConfirmed,
                    activeDropTarget,
                    activeDropAttempts
                )
                return
            end

            Info.Text = string.format(
                "%d rows  •  %d total owned  •  %d mail/drop  •  %d fruits",
                #State.LatestItems,
                totalUnits,
                droppableTypes,
                fruitCount
            )
        end

        local function requiredVirtualRows()
            local viewportHeight = Scroll.AbsoluteWindowSize.Y
            if not viewportHeight or viewportHeight <= 0 then
                viewportHeight = Scroll.AbsoluteSize.Y
            end

            local required = math.ceil(
                math.max(viewportHeight, VIRTUAL_ROW_HEIGHT)
                / VIRTUAL_ROW_STRIDE
            ) + VIRTUAL_BUFFER_ROWS

            return math.clamp(required, VIRTUAL_MIN_ROWS, VIRTUAL_MAX_ROWS)
        end

        local function createVirtualRow()
            local Row = C(N("Frame", {
                Name = "InventoryItemRow",
                Position = UDim2.new(0, 1, 0, 0),
                Size = UDim2.new(1, -4, 0, VIRTUAL_ROW_HEIGHT),
                BackgroundColor3 = T.Surface2,
                BackgroundTransparency = .05,
                BorderSizePixel = 0,
                Visible = false,
            }, Scroll), 6)
            S(Row, T.Line, .70, 1)

            local Check = C(N("TextButton", {
                Name = "Select",
                Text = "",
                Position = UDim2.fromOffset(8, 11),
                Size = UDim2.fromOffset(24, 24),
                BackgroundColor3 = T.Surface3,
                BorderSizePixel = 0,
                TextColor3 = T.White,
                Font = T.Font,
                TextSize = 13,
                AutoButtonColor = false,
            }, Row), 5)
            S(Check, T.Line, .58, 1)

            local Name = label(
                Row,
                "",
                UDim2.fromOffset(45, 5),
                UDim2.new(.57, -45, 0, 20),
                11,
                T.White,
                T.Font
            )
            Name.TextTruncate = Enum.TextTruncate.AtEnd

            local Rarity = label(
                Row,
                "",
                UDim2.fromOffset(45, 27),
                UDim2.new(.57, -45, 0, 16),
                9,
                T.Muted,
                T.Font
            )
            Rarity.TextTruncate = Enum.TextTruncate.AtEnd

            local Qty = C(N("TextBox", {
                Name = "Qty",
                Position = UDim2.new(.69, 0, .5, -16),
                Size = UDim2.new(.14, 0, 0, 32),
                BackgroundColor3 = Color3.fromRGB(7, 7, 11),
                BorderSizePixel = 0,
                Text = "",
                PlaceholderText = "Qty",
                PlaceholderColor3 = T.Muted,
                TextColor3 = T.White,
                Font = T.Body,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Center,
                ClearTextOnFocus = false,
            }, Row), 7)
            S(Qty, T.Line, .58, 1)

            local Owned = label(
                Row,
                "",
                UDim2.new(.84, 4, 0, 0),
                UDim2.new(.16, -12, 1, 0),
                10,
                T.Muted,
                T.Body,
                Enum.TextXAlignment.Right
            )

            local record = {
                Frame = Row,
                Check = Check,
                Name = Name,
                Rarity = Rarity,
                Qty = Qty,
                Owned = Owned,
                Data = nil,
            }

            TrackConnection(Check.Activated:Connect(function()
                local data = record.Data
                if not data or State.QueueRunning then
                    return
                end

                if not data.Droppable or not data.DropCategory then
                    setHeaderStatus("DISPLAY ONLY", T.Muted)
                    Info.Text = data.Name
                        .. " is not classified as mailable by the current inventory rules."
                    return
                end

                State.Selected[data.Key] = not State.Selected[data.Key]
                if State.Selected[data.Key] then
                    if data.IsFruit then
                        State.Quantities[data.Key] = 1
                    elseif not State.Quantities[data.Key] then
                        State.Quantities[data.Key] = 1
                    end
                end
                updateInfo()
                renderVirtualRows()
            end))

            TrackConnection(Qty.FocusLost:Connect(function()
                local data = record.Data
                if not data then
                    return
                end

                if data.IsFruit then
                    State.Quantities[data.Key] = 1
                    Qty.Text = "1"
                    return
                end

                local raw = trim(Qty.Text)
                if raw == "" then
                    State.Quantities[data.Key] = nil
                    return
                end

                local amount = math.clamp(
                    math.max(1, math.floor(tonumber(raw) or 1)),
                    1,
                    math.max(1, data.Count)
                )
                State.Quantities[data.Key] = amount
                Qty.Text = tostring(amount)
            end))

            State.RowPool[#State.RowPool + 1] = record
            return record
        end

        local function ensureVirtualRowPool()
            local required = requiredVirtualRows()
            while #State.RowPool < required do
                createVirtualRow()
            end
        end

        local function updateVirtualRow(record, data, itemIndex)
            -- Inventory rows are virtualized and the same physical Frame is reused for
            -- different items while scrolling. Hide the WHOLE row while rebinding it.
            -- Showing the parent before all children were updated allowed one rendered
            -- frame where the new item name could be paired with the old FAV/UNFAV state.
            record.Frame.Visible = false
            record.Data = data

            local targetY = (itemIndex - 1) * VIRTUAL_ROW_STRIDE + 1
            record.Frame.Position = UDim2.new(0, 1, 0, targetY)

            local selected = State.Selected[data.Key] == true
            local isActive = running
                and data.DropCategory == activeDropCategory
                and data.Name == activeDropName
                and (data.ItemKey == nil or tostring(data.ItemKey) == tostring(activeDropItemKey))

            record.Name.Text = data.DisplayName or data.Name

            if data.IsFruit then
                local mutation = tostring(data.Mutation or "Normal")
                record.Rarity.Text = mutation .. "  •  " .. inventoryFormatFruitMultiplier(data.Multiplier)
                record.Rarity.TextColor3 = T.Success

                -- Same value style as Garden: bold theme font + gold warning color + "$ amount".
                record.Owned.Text = "$ " .. inventoryFormatFruitValue(data.Value)
                record.Owned.TextColor3 = INVENTORY_FRUIT_VALUE_COLOR
                record.Owned.Font = T.Font
                record.Owned.TextSize = 11
            else
                -- Restore the normal item-owned style when a virtual row is recycled.
                record.Owned.TextColor3 = T.Muted
                record.Owned.Font = T.Body
                record.Owned.TextSize = 10

                local rarity = tostring(data.Rarity or "Unknown")
                if rarity == "Unknown" then
                    record.Rarity.Text = data.Category
                    record.Rarity.TextColor3 = T.Muted
                else
                    record.Rarity.Text = rarity
                    record.Rarity.TextColor3 = INVENTORY_RARITY_COLORS[rarity] or T.Muted
                end
                record.Owned.Text = "Owned  " .. tostring(data.Count)
            end

            local storedQty = State.Quantities[data.Key]
            if data.IsFruit then
                State.Quantities[data.Key] = 1
                if not record.Qty:IsFocused() then
                    record.Qty.Text = "1"
                end
                record.Qty.TextEditable = false
                record.Qty.PlaceholderText = "1"
                record.Qty.BackgroundColor3 = T.Surface3
            else
                if not record.Qty:IsFocused() then
                    record.Qty.Text = storedQty and tostring(storedQty) or ""
                end
                record.Qty.TextEditable = data.Droppable and not State.QueueRunning
                record.Qty.PlaceholderText = data.Droppable and "Qty" or "--"
                record.Qty.BackgroundColor3 = data.Droppable
                    and Color3.fromRGB(7, 7, 11)
                    or T.Surface3
            end

            if isActive then
                record.Check.Text = "…"
                record.Check.BackgroundColor3 = T.Red
                record.Check.TextColor3 = T.White
            elseif selected then
                record.Check.Text = "✓"
                record.Check.BackgroundColor3 = T.RedDark
                record.Check.TextColor3 = T.White
            else
                record.Check.Text = ""
                record.Check.BackgroundColor3 = T.Surface3
                record.Check.TextColor3 = T.White
            end

            record.Check.Active = data.Droppable and not State.QueueRunning
            record.Frame.BackgroundTransparency = selected and .00 or .05

            -- Publish the completely rebound row in one step. This keeps the pet/fruit
            -- favorite button visually attached to the correct item during fast scroll.
            record.Frame.Visible = true
        end

        renderVirtualRows = function()
            ensureVirtualRowPool()
            FavoriteRuntime.BeginButtonPass()

            local firstIndex = math.floor(
                math.max(0, Scroll.CanvasPosition.Y) / VIRTUAL_ROW_STRIDE
            ) + 1

            local poolIndex = 1
            for itemIndex = firstIndex, math.min(
                #State.VisibleItems,
                firstIndex + #State.RowPool - 1
            ) do
                local data = State.VisibleItems[itemIndex]
                local record = State.RowPool[poolIndex]
                updateVirtualRow(record, data, itemIndex)
                FavoriteRuntime.RenderButton(data, itemIndex)
                poolIndex += 1
            end

            for index = poolIndex, #State.RowPool do
                local record = State.RowPool[index]
                record.Data = nil
                record.Frame.Visible = false
            end

            FavoriteRuntime.EndButtonPass()
        end

        refreshInventory = function(resetScroll)
            local rows = collectInventory()
            FavoriteRuntime.Prune(rows)
            State.LatestItems = rows
            State.LastSignature = inventorySignature(rows)
            InventoryRefreshDirty = false
            InventoryRefreshResetScroll = false
            updateInfo()
            applyFilters(resetScroll == true)
        end

        stopDropJob = function(reason)
            if not running then
                return
            end

            runId += 1
            running = false
            setHeaderStatus("STOPPED", T.Red)
            Info.Text = tostring(reason or "Drop job stopped.")
            renderVirtualRows()
        end

        runDrop = function(category, itemName, requestedAmount, itemKey, displayName)
            if not RequestDrop then
                setHeaderStatus("ERROR", T.Red)
                Info.Text = "Networking.DroppedItem.RequestDrop was not found."
                return
            end

            if automationIsBusy() then
                setHeaderStatus("AUTOMATION ACTIVE", T.Red)
                Info.Text = "Stop Auto Plant / Auto Harvest / Auto Sell / Auto Trowel before dropping."
                return
            end

            local startingCount = getOwnedCount(category, itemName, itemKey)
            if startingCount <= 0 then
                setHeaderStatus("NOT FOUND", T.Red)
                Info.Text = "The selected item is no longer in inventory."
                refreshInventory(true)
                return
            end

            local actualDropAmount = math.min(
                math.max(1, math.floor(requestedAmount)),
                startingCount
            )
            local targetRemaining = startingCount - actualDropAmount
            local myRunId = runId + 1
            runId = myRunId
            running = true

            activeDropCategory = category
            activeDropName = itemName
            activeDropItemKey = itemKey
            activeDropDisplayName = displayName or itemName
            activeDropTarget = actualDropAmount
            activeDropConfirmed = 0
            activeDropAttempts = 0

            setHeaderStatus("DROPPING", T.Success)
            updateInfo()
            renderVirtualRows()

            task.spawn(function()
                local requestAttempts = 0
                local consecutiveFailures = 0
                local completed = false
                local stopReason = nil
                local hasConfirmedFirstDrop = false
                local lastRequestFireAt = nil
                local lastConfirmedAt = nil
                local isDirectFruitDrop = category == "HarvestedFruits"
                    and itemKey ~= nil
                    and tostring(itemKey) ~= ""

                local function waitForRequestSlot()
                    if not lastRequestFireAt and not lastConfirmedAt then
                        return true
                    end

                    local now = os.clock()
                    local fireRemaining = lastRequestFireAt
                        and (FOLLOWUP_REQUEST_INTERVAL - (now - lastRequestFireAt))
                        or 0
                    local confirmRemaining = lastConfirmedAt
                        and (POST_CONFIRM_REQUEST_DELAY - (now - lastConfirmedAt))
                        or 0
                    local remaining = math.max(0, fireRemaining, confirmRemaining)

                    if remaining > 0 then
                        local finishAt = os.clock() + remaining
                        while os.clock() < finishAt do
                            if myRunId ~= runId then
                                return false
                            end
                            task.wait(math.min(0.05, finishAt - os.clock()))
                        end
                    end

                    return myRunId == runId
                end

                while myRunId == runId do
                    local currentCount = getOwnedCount(category, itemName, itemKey)

                    if currentCount <= targetRemaining then
                        completed = true
                        stopReason = "Target remaining count reached."
                        break
                    end

                    if currentCount <= 0 then
                        stopReason = "Item no longer exists in inventory."
                        break
                    end

                    local heldTool = nil
                    local holdError = nil

                    if isDirectFruitDrop then
                        heldTool, holdError = FruitHold.Ensure(itemKey)
                    else
                        heldTool, holdError = ensureItemHeld(category, itemName, itemKey)
                    end

                    if myRunId ~= runId then
                        break
                    end

                    if not heldTool then
                        consecutiveFailures += 1
                        setHeaderStatus("HOLD RETRY", T.Red)
                        Info.Text = tostring(holdError)
                            .. "  •  retry "
                            .. tostring(consecutiveFailures)
                            .. "/"
                            .. tostring(MAX_CONSECUTIVE_TIMEOUTS)

                        if consecutiveFailures >= MAX_CONSECUTIVE_TIMEOUTS then
                            stopReason = "Could not hold selected item."
                            break
                        end

                        task.wait(RETRY_DELAY)
                        continue
                    end

                    if not waitForRequestSlot() then
                        break
                    end

                    local before = getOwnedCount(category, itemName, itemKey)
                    if before <= targetRemaining then
                        completed = true
                        stopReason = "Target remaining count reached."
                        break
                    end

                    requestAttempts += 1
                    activeDropAttempts = requestAttempts
                    updateInfo()
                    renderVirtualRows()

                    if isDirectFruitDrop then
                        local fruitHeld = FruitHold.IsHeld(itemKey)
                        if not fruitHeld then
                            consecutiveFailures += 1
                            setHeaderStatus("HOLD RETRY", T.Red)
                            Info.Text = "Harvested fruit stopped being selected before RequestDrop."
                            task.wait(RETRY_DELAY)
                            continue
                        end
                    else
                        local character = LocalPlayer.Character
                        if not character or not heldTool or heldTool.Parent ~= character then
                            consecutiveFailures += 1
                            task.wait(RETRY_DELAY)
                            continue
                        end
                    end

                    -- Normal Tools use Humanoid:EquipTool(). Harvested fruits use the
                    -- game's InventoryController Select path first, then RequestDrop
                    -- receives HarvestedFruits + the exact unique fruit Id.
                    local requestItemKey = getRequestDropItemKey(heldTool, category, itemName, itemKey)
                    local requestFireAt = nil
                    local fired, fireError = pcall(function()
                        requestFireAt = os.clock()
                        RequestDrop:Fire(category, requestItemKey)
                    end)

                    if not fired then
                        consecutiveFailures += 1
                        setHeaderStatus("FIRE RETRY", T.Red)
                        Info.Text = tostring(fireError)

                        if consecutiveFailures >= MAX_CONSECUTIVE_TIMEOUTS then
                            stopReason = "Too many consecutive Fire/hold failures."
                            break
                        end

                        task.wait(RETRY_DELAY)
                        continue
                    end

                    lastRequestFireAt = requestFireAt or os.clock()

                    local confirmationTimeout = hasConfirmedFirstDrop
                        and FOLLOWUP_CONFIRM_TIMEOUT
                        or FIRST_DROP_CONFIRM_TIMEOUT

                    local changed, after, _, cancelled = waitForInventoryDecrease(
                        category,
                        itemName,
                        itemKey,
                        before,
                        confirmationTimeout,
                        myRunId
                    )

                    if cancelled or myRunId ~= runId then
                        break
                    end

                    if changed then
                        consecutiveFailures = 0
                        hasConfirmedFirstDrop = true
                        lastConfirmedAt = os.clock()

                        local totalConfirmed = math.max(0, startingCount - after)
                        activeDropConfirmed = math.min(totalConfirmed, actualDropAmount)
                        setHeaderStatus("DROPPING", T.Success)
                        refreshInventory(false)

                        if after <= targetRemaining then
                            completed = true
                            stopReason = "Target remaining count reached."
                            break
                        end
                    else
                        consecutiveFailures += 1
                        setHeaderStatus("REQUEST IGNORED", T.Red)
                        Info.Text = "Inventory stayed at "
                            .. tostring(after)
                            .. ". Retrying "
                            .. tostring(consecutiveFailures)
                            .. "/"
                            .. tostring(MAX_CONSECUTIVE_TIMEOUTS)
                            .. "."

                        if consecutiveFailures >= MAX_CONSECUTIVE_TIMEOUTS then
                            stopReason = "Too many consecutive ignored requests/timeouts."
                            break
                        end

                        task.wait(RETRY_DELAY)
                    end
                end

                if not isDirectFruitDrop then
                    unholdSelectedItem(category, itemName, itemKey)
                end

                if myRunId == runId then
                    local finalCount = getOwnedCount(category, itemName, itemKey)
                    local confirmedTotal = math.max(0, startingCount - finalCount)
                    running = false
                    activeDropConfirmed = math.min(confirmedTotal, actualDropAmount)

                    refreshInventory(false)

                    if completed then
                        setHeaderStatus("FINISHED", T.Success)
                        Info.Text = tostring(confirmedTotal)
                            .. " "
                            .. tostring(displayName or itemName)
                            .. " dropped successfully  •  "
                            .. tostring(finalCount)
                            .. " remaining"
                    else
                        setHeaderStatus("STOPPED", T.Red)
                        Info.Text = tostring(stopReason or "Drop job stopped.")
                    end

                    renderVirtualRows()
                end
            end)
        end

        runSelectedQueue = function()
            if State.QueueRunning then
                State.QueueRunId += 1
                State.QueueRunning = false
                DropSelectedButton.Text = "DROP"
                DropSelectedButton.BackgroundColor3 = T.RedDark

                local category = activeDropCategory
                local itemName = activeDropName
                local itemKey = activeDropItemKey
                stopDropJob("Drop queue stopped by user.")
                if category and itemName then
                    task.spawn(function()
                        unholdSelectedItem(category, itemName, itemKey)
                        task.wait(0.05)
                        refreshInventory(false)
                    end)
                end
                return
            end

            local jobs = {}
            for _, item in ipairs(State.LatestItems) do
                if State.Selected[item.Key] and item.Droppable and item.DropCategory then
                    local amount
                    if item.IsFruit then
                        amount = 1
                    else
                        amount = math.clamp(
                            math.max(1, math.floor(tonumber(State.Quantities[item.Key]) or 1)),
                            1,
                            math.max(1, item.Count)
                        )
                    end
                    State.Quantities[item.Key] = amount
                    jobs[#jobs + 1] = {
                        Key = item.Key,
                        Name = item.Name,
                        DisplayName = item.DisplayName or item.Name,
                        Category = item.DropCategory,
                        ItemKey = item.ItemKey,
                        Amount = amount,
                        IsFruit = item.IsFruit == true,
                    }
                end
            end

            if #jobs == 0 then
                setHeaderStatus("NOTHING SELECTED", T.Red)
                Info.Text = "Check one or more mailable items and enter Qty for each."
                if Notify then
                    Notify("Inventory", "Check one or more items and enter Qty for each.", 2)
                end
                return
            end

            if automationIsBusy() then
                setHeaderStatus("AUTOMATION ACTIVE", T.Red)
                Info.Text = "Stop Auto Plant / Auto Harvest / Auto Sell / Auto Trowel before dropping."
                return
            end

            State.QueueRunId += 1
            local myQueueId = State.QueueRunId
            State.QueueRunning = true
            DropSelectedButton.Text = "STOP"
            DropSelectedButton.BackgroundColor3 = T.Red
            renderVirtualRows()

            task.spawn(function()
                for index, job in ipairs(jobs) do
                    if not alive or myQueueId ~= State.QueueRunId or not State.QueueRunning then
                        break
                    end

                    Info.Text = string.format(
                        "Queue %d/%d  •  %s  •  Qty %d",
                        index,
                        #jobs,
                        job.DisplayName or job.Name,
                        job.Amount
                    )

                    runDrop(job.Category, job.Name, job.Amount, job.ItemKey, job.DisplayName)

                    while alive
                        and myQueueId == State.QueueRunId
                        and State.QueueRunning
                        and running do
                        task.wait(0.05)
                    end

                    if myQueueId ~= State.QueueRunId or not State.QueueRunning then
                        break
                    end

                    if activeDropName == job.Name
                        and activeDropCategory == job.Category
                        and (job.ItemKey == nil or tostring(activeDropItemKey) == tostring(job.ItemKey))
                        and activeDropConfirmed >= job.Amount then
                        State.Selected[job.Key] = nil
                        State.Quantities[job.Key] = nil
                    end

                    task.wait(0.05)
                end

                if myQueueId == State.QueueRunId then
                    State.QueueRunning = false
                    DropSelectedButton.Text = "DROP"
                    DropSelectedButton.BackgroundColor3 = T.RedDark
                    refreshInventory(false)
                    renderVirtualRows()

                    if not running then
                        setHeaderStatus("READY", T.Success)
                        updateInfo()
                    end
                end
            end)
        end

        for key, button in pairs(InventoryTabButtons) do
            TrackConnection(button.Activated:Connect(function()
                State.CurrentTab = key
                updateInventoryTabs()
                applyFilters(true)
            end))
        end

        TrackConnection(Search:GetPropertyChangedSignal("Text"):Connect(function()
            State.SearchText = Search.Text
            applyFilters(true)
        end))

        TrackConnection(DropSelectedButton.Activated:Connect(function()
            runSelectedQueue()
        end))

        TrackConnection(RefreshButton.Activated:Connect(function()
            requestInventoryFruitValueRefresh()
            refreshInventory(false)
            setHeaderStatus(running and "DROPPING" or "REFRESHED", T.Success)
        end))

        TrackConnection(Scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
            renderVirtualRows()
        end))

        TrackConnection(Scroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
            renderVirtualRows()
        end))

        -- V69 PERFORMANCE: coalesce bursts of Backpack/Character changes into one
        -- refresh. If Inventory is hidden we only mark it dirty; opening the page
        -- performs one fresh scan instead of doing background work.
        local function scheduleInventoryRefresh(delaySeconds, resetScroll)
            InventoryRefreshDirty = true
            if resetScroll then
                InventoryRefreshResetScroll = true
            end

            if not alive or not Inventory.Visible or InventoryRefreshScheduled then
                return
            end

            InventoryRefreshScheduled = true
            task.delay(delaySeconds or 0.08, function()
                InventoryRefreshScheduled = false

                if not alive or not Inventory.Visible or not InventoryRefreshDirty then
                    return
                end

                local shouldReset = InventoryRefreshResetScroll
                refreshInventory(shouldReset)
            end)
        end

        local function watchInventoryStack(instance)
            if not instance or InventoryCountWatchers[instance] then
                return
            end
            if not instance:IsA("Tool") and instance:GetAttribute("HarvestedFruit") ~= true then
                return
            end

            local connections = {}
            if instance:IsA("Tool") then
                connections[#connections + 1] = instance:GetAttributeChangedSignal("Count"):Connect(function()
                    -- Count changes are the normal path for stacked Seeds/Gear/Crates/etc.
                    scheduleInventoryRefresh(0.06, false)
                end)
            end
            connections[#connections + 1] = instance:GetAttributeChangedSignal("IsFavorite"):Connect(function()
                scheduleInventoryRefresh(0.02, false)
            end)
            connections[#connections + 1] = instance:GetAttributeChangedSignal("Favorite"):Connect(function()
                scheduleInventoryRefresh(0.02, false)
            end)

            InventoryCountWatchers[instance] = connections
            for _, connection in ipairs(connections) do
                TrackConnection(connection)
            end
        end

        local CharacterChildAddedConnection
        local CharacterChildRemovedConnection

        local function bindCharacterInventory(character)
            if CharacterChildAddedConnection then
                CharacterChildAddedConnection:Disconnect()
                CharacterChildAddedConnection = nil
            end
            if CharacterChildRemovedConnection then
                CharacterChildRemovedConnection:Disconnect()
                CharacterChildRemovedConnection = nil
            end

            if not character then
                return
            end

            for _, instance in ipairs(character:GetChildren()) do
                watchInventoryStack(instance)
            end

            CharacterChildAddedConnection = character.ChildAdded:Connect(function(instance)
                watchInventoryStack(instance)
                scheduleInventoryRefresh(0.06, false)
            end)
            CharacterChildRemovedConnection = character.ChildRemoved:Connect(function()
                scheduleInventoryRefresh(0.06, false)
            end)
            TrackConnection(CharacterChildAddedConnection)
            TrackConnection(CharacterChildRemovedConnection)
        end

        for _, instance in ipairs(Backpack:GetChildren()) do
            watchInventoryStack(instance)
        end
        bindCharacterInventory(LocalPlayer.Character)

        TrackConnection(Backpack.ChildAdded:Connect(function(instance)
            watchInventoryStack(instance)
            scheduleInventoryRefresh(0.06, false)
        end))
        TrackConnection(Backpack.ChildRemoved:Connect(function()
            scheduleInventoryRefresh(0.06, false)
        end))

        TrackConnection(LocalPlayer.CharacterAdded:Connect(function(character)
            bindCharacterInventory(character)
            InventoryToolMetadataCache = setmetatable({}, { __mode = "k" })
            scheduleInventoryRefresh(0.25, false)
        end))

        -- Safety reconciliation is visibility-driven. It exists only while this page
        -- is open and catches rare changes that do not touch Backpack children or Count.
        local function restartInventoryReconciler()
            InventoryReconcileGeneration += 1
            local myGeneration = InventoryReconcileGeneration

            if not alive or not Inventory.Visible then
                return
            end

            requestInventoryFruitValueRefresh()
            scheduleInventoryRefresh(0, false)
            setHeaderStatus(running and "DROPPING" or "READY", T.Success)

            task.spawn(function()
                while alive
                    and Inventory.Visible
                    and InventoryReconcileGeneration == myGeneration do

                    task.wait(3.0)

                    if not alive
                        or not Inventory.Visible
                        or InventoryReconcileGeneration ~= myGeneration then
                        break
                    end

                    local rows = collectInventory()
                    local signature = inventorySignature(rows)
                    if signature ~= State.LastSignature then
                        State.LatestItems = rows
                        State.LastSignature = signature
                        InventoryRefreshDirty = false
                        updateInfo()
                        applyFilters(false)
                    end
                end
            end)
        end

        TrackConnection(Inventory:GetPropertyChangedSignal("Visible"):Connect(function()
            if Inventory.Visible then
                -- Always treat opening as dirty because Mail fruit values/multipliers can
                -- change while Inventory is hidden without touching Backpack children.
                InventoryRefreshDirty = true
            end
            restartInventoryReconciler()
        end))

        _G.ScoopHubInventoryAPI = {
            Stop = function()
                State.QueueRunId += 1
                State.QueueRunning = false
                DropSelectedButton.Text = "DROP"
                DropSelectedButton.BackgroundColor3 = T.RedDark
                local category = activeDropCategory
                local itemName = activeDropName
                local itemKey = activeDropItemKey
                stopDropJob("Inventory drop stopped.")
                if category and itemName then
                    task.spawn(function()
                        unholdSelectedItem(category, itemName, itemKey)
                        task.wait(0.05)
                        refreshInventory(false)
                    end)
                end
            end,
            Refresh = function()
                InventoryRefreshDirty = true
                if Inventory.Visible then
                    scheduleInventoryRefresh(0, false)
                else
                    -- Explicit API refresh keeps its old semantics even while hidden.
                    refreshInventory(false)
                end
            end,
            IsRunning = function()
                return running
            end,
        }

        RegisterScoopHubCleanup(function()
            if _G.ScoopHubInventoryAPI and _G.ScoopHubInventoryAPI.Stop then
                pcall(_G.ScoopHubInventoryAPI.Stop)
            end
        end)

        updateInventoryTabs()
        if Inventory.Visible then
            refreshInventory(true)
            restartInventoryReconciler()
        else
            -- Lazy first build: opening Inventory performs the authoritative scan.
            InventoryRefreshDirty = true
        end
        print("[ScoopHub] Inventory page initialized (V69 event-driven performance optimization).")
    end

    local __inventoryInitOk, __inventoryInitErr = pcall(__ScoopHubInitInventoryDrop)
    if not __inventoryInitOk then
        warn("[ScoopHub] Inventory init error: " .. tostring(__inventoryInitErr))
        pcall(function()
            for _, child in ipairs(Inventory:GetChildren()) do
                child:Destroy()
            end

            local ErrorPanel = panel(
                Inventory,
                UDim2.fromScale(0, 0),
                UDim2.fromScale(1, 1),
                "INVENTORY"
            )

            local errLabel = label(
                ErrorPanel,
                "Inventory failed to initialize:\n" .. tostring(__inventoryInitErr),
                UDim2.new(0, 12, 0, 34),
                UDim2.new(1, -24, 1, -46),
                9,
                T.Red,
                T.Body
            )
            errLabel.TextWrapped = true
            errLabel.TextYAlignment = Enum.TextYAlignment.Top
        end)
    end



    --==================================================
    -- MISC PAGE
    --==================================================
    local function __ScoopHubInitMisc()
        local TeleportService = game:GetService("TeleportService")
        local HttpService = game:GetService("HttpService")
        local RunService = game:GetService("RunService")
        local GuiService = game:GetService("GuiService")
        local Workspace = game:GetService("Workspace")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")

        local State = _G.ScoopHubMiscState or {
            AutoRejoin = false,
            WalkSpeed = 16,
            JumpPower = 50,
            NoClip = false,
            InfiniteJump = false,
            FPS = "60",
            RemoveOtherGardens = false,
            BackpackValueESP = false,
            GardenESPEnabled = false,
            GardenESPFruitAll = false,
            GardenESPFruits = {},
            GardenESPMutationAll = true,
            GardenESPMutations = {},
        }
        _G.ScoopHubMiscState = State

        -- Preference toggles begin OFF each execution. Named Config auto-load runs
        -- after User/Misc initialization and may explicitly restore AutoRejoin.
        State.AutoRejoin = false
        State.BackpackValueESP = false
        State.GardenESPEnabled = false
        State.GardenESPFruitAll = false
        State.GardenESPFruits = {}
        State.GardenESPMutationAll = true
        State.GardenESPMutations = {}

        State.WalkSpeed = tonumber(State.WalkSpeed) or 16
        State.JumpPower = tonumber(State.JumpPower) or 50
        State.FPS = tostring(State.FPS or "60")

        local Page = Misc
        Page.ClipsDescendants = false

        local Title = label(
            Page,
            "MISC OPTIONS",
            UDim2.new(0, 4, 0, 1),
            UDim2.new(1, -8, 0, 20),
            11,
            T.Text,
            T.Font
        )

        local Divider = N("Frame", {
            Position = UDim2.new(0, 4, 0, 22),
            Size = UDim2.new(1, -8, 0, 1),
            BackgroundColor3 = T.Red,
            BackgroundTransparency = .5,
            BorderSizePixel = 0,
        }, Page)

        -- Misc keeps 65px cards and scrolling, but the layout is now styled more
        -- like Config: cleaner outer margins, a reserved scrollbar gutter, and a
        -- padded content area so the cards do not feel cramped against the page.
        local CARD_H = 65
        local ROW_GAP = 4
        local START_Y = 0
        local MISC_ROWS = 7
        local GARDEN_ESP_CARD_H = 170
        local CONTENT_H =
            ((MISC_ROWS - 1) * CARD_H)
            + ((MISC_ROWS - 1) * ROW_GAP)
            + GARDEN_ESP_CARD_H

        local MiscScroll = N("ScrollingFrame", {
            Name = "MiscScroll",
            Position = UDim2.new(0, 0, 0, 28),
            Size = UDim2.new(1, 0, 1, -28),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.new(0, 0, 0, CONTENT_H + 8),
            ScrollBarThickness = 3,
            ScrollBarImageColor3 = T.Red,
            ScrollBarImageTransparency = .18,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
            VerticalScrollBarInset = Enum.ScrollBarInset.Always,
            ClipsDescendants = true,
            ZIndex = 1,
        }, Page)

        local MiscContent = N("Frame", {
            Name = "MiscContent",
            -- 1px inset keeps the card UIStroke inside the ScrollingFrame clip.
            -- Without this, the left/top half of the 1px stroke is clipped at x/y=0.
            Position = UDim2.new(0, 1, 0, 1),
            Size = UDim2.new(1, -10, 0, CONTENT_H),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 1,
        }, MiscScroll)

        local function card(col, row, titleText, description)
            local xScale = col == 1 and 0 or .5
            local xOffset = col == 1 and 0 or 3
            local widthOffset = -3
            local y = START_Y + ((row - 1) * (CARD_H + ROW_GAP))

            local f = C(N("Frame", {
                Position = UDim2.new(xScale, xOffset, 0, y),
                Size = UDim2.new(.5, widthOffset, 0, CARD_H),
                BackgroundColor3 = T.Surface2,
                BackgroundTransparency = .06,
                BorderSizePixel = 0,
                ClipsDescendants = false,
                ZIndex = 2,
            }, MiscContent), 7)
            S(f, T.Line, .48, 1)

            N("Frame", {
                Position = UDim2.new(0, 8, 0, 0),
                Size = UDim2.new(0, 32, 0, 2),
                BackgroundColor3 = T.Red,
                BackgroundTransparency = .18,
                BorderSizePixel = 0,
                ZIndex = 3,
            }, f)

            label(
                f,
                titleText,
                UDim2.new(0, 10, 0, 8),
                UDim2.new(1, -20, 0, 18),
                11,
                T.White,
                T.Font
            )

            if description and description ~= "" then
                local desc = label(
                    f,
                    description,
                    UDim2.new(0, 10, 0, 25),
                    UDim2.new(1, -20, 0, 26),
                    9,
                    T.Muted,
                    T.Body
                )
                desc.TextWrapped = true
                desc.TextYAlignment = Enum.TextYAlignment.Top
            end

            return f
        end

        local function makeToggle(parent, initial, onChanged)
            local value = initial == true

            local b = C(N("TextButton", {
                Text = "",
                AutoButtonColor = false,
                AnchorPoint = Vector2.new(1, .5),
                Position = UDim2.new(1, -9, .5, 6),
                Size = UDim2.fromOffset(43, 22),
                BackgroundColor3 = value and T.Red or T.Surface3,
                BorderSizePixel = 0,
                ZIndex = 5,
            }, parent), 11)

            local knob = C(N("Frame", {
                AnchorPoint = Vector2.new(0, .5),
                Position = value and UDim2.new(1, -20, .5, 0) or UDim2.new(0, 3, .5, 0),
                Size = UDim2.fromOffset(17, 17),
                BackgroundColor3 = T.White,
                BorderSizePixel = 0,
                ZIndex = 6,
            }, b), 9)

            local control = {}

            function control:Set(newValue, fireCallback)
                value = newValue == true
                b.BackgroundColor3 = value and T.Red or T.Surface3
                tw(knob, {
                    Position = value and UDim2.new(1, -20, .5, 0) or UDim2.new(0, 3, .5, 0),
                }, .12)

                if fireCallback ~= false and onChanged then
                    onChanged(value)
                end
            end

            function control:Get()
                return value
            end

            b.Activated:Connect(function()
                control:Set(not value, true)
            end)

            return control
        end

        local function makeValueBox(parent, textValue, onCommit)
            local box = C(N("TextBox", {
                Text = tostring(textValue),
                ClearTextOnFocus = false,
                Font = T.Font,
                TextSize = 10,
                TextColor3 = T.White,
                TextXAlignment = Enum.TextXAlignment.Left,
                BackgroundColor3 = T.Input,
                BorderSizePixel = 0,
                Position = UDim2.new(0, 9, 0, 34),
                Size = UDim2.new(1, -18, 0, 20),
                ZIndex = 4,
            }, parent), 5)
            N("UIPadding", { PaddingLeft = UDim.new(0, 8) }, box)
            S(box, T.Line, .72, 1)

            box.FocusLost:Connect(function()
                if onCommit then
                    onCommit(box)
                end
            end)

            return box
        end

        local function makeAction(parent, textValue, callback)
            local b = C(N("TextButton", {
                Text = textValue,
                AutoButtonColor = false,
                Font = T.Font,
                TextSize = 10,
                TextColor3 = T.White,
                BackgroundColor3 = T.RedDark,
                BorderSizePixel = 0,
                Position = UDim2.new(0, 9, 0, 34),
                Size = UDim2.new(1, -18, 0, 20),
                ZIndex = 4,
            }, parent), 5)
            S(b, T.Red, .45, 1)

            b.MouseEnter:Connect(function()
                tw(b, { BackgroundColor3 = T.Red }, .1)
            end)
            b.MouseLeave:Connect(function()
                tw(b, { BackgroundColor3 = T.RedDark }, .1)
            end)
            b.Activated:Connect(callback)
            return b
        end

        local function getHumanoid()
            local character = LP.Character
            return character and character:FindFirstChildOfClass("Humanoid")
        end

        local function applyMovement()
            local humanoid = getHumanoid()
            if not humanoid then return end

            pcall(function()
                humanoid.WalkSpeed = State.WalkSpeed
            end)

            pcall(function()
                humanoid.UseJumpPower = true
                humanoid.JumpPower = State.JumpPower
            end)
        end

        TrackConnection(LP.CharacterAdded:Connect(function(character)
            local humanoid = character:WaitForChild("Humanoid", 10)
            if humanoid then
                task.wait(.15)
                applyMovement()
            end
        end))

        -- AUTO REJOIN -----------------------------------------------------------
        local reconnectBusy = false
        local AutoRejoinCard = card(1, 1, "AUTO REJOIN", "Rejoin this server if disconnected.")
        local AutoRejoinToggle = makeToggle(AutoRejoinCard, State.AutoRejoin, function(enabled)
            State.AutoRejoin = enabled
        end)

        TrackConnection(GuiService.ErrorMessageChanged:Connect(function(message)
            if not State.AutoRejoin or reconnectBusy then return end
            if tostring(message or "") == "" then return end

            reconnectBusy = true
            task.delay(2, function()
                queueScoopHubAfterTeleport()
                pcall(function()
                    if game.JobId and game.JobId ~= "" then
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP)
                    else
                        TeleportService:Teleport(game.PlaceId, LP)
                    end
                end)
                task.delay(5, function()
                    reconnectBusy = false
                end)
            end)
        end))

        -- WALK SPEED ------------------------------------------------------------
        local WalkCard = card(2, 1, "WALK SPEED", "Player movement speed.")
        local WalkBox = makeValueBox(WalkCard, State.WalkSpeed, function(box)
            local value = tonumber(box.Text)
            if not value then
                box.Text = tostring(State.WalkSpeed)
                return
            end
            State.WalkSpeed = math.clamp(value, 0, 500)
            box.Text = tostring(State.WalkSpeed)
            applyMovement()
        end)

        -- JUMP POWER ------------------------------------------------------------
        local JumpCard = card(1, 2, "JUMP POWER", "Player jump power.")
        local JumpBox = makeValueBox(JumpCard, State.JumpPower, function(box)
            local value = tonumber(box.Text)
            if not value then
                box.Text = tostring(State.JumpPower)
                return
            end
            State.JumpPower = math.clamp(value, 0, 500)
            box.Text = tostring(State.JumpPower)
            applyMovement()
        end)

        -- NO CLIP ---------------------------------------------------------------
        -- Plant-only noclip for the local player's own garden.
        -- Target: Workspace > Gardens > <owned Plot#> > Plants
        -- We disable collision on the plant parts themselves instead of disabling
        -- collision on the character, so the player still collides with the ground
        -- and the rest of the map normally.
        local collisionCache = setmetatable({}, { __mode = "k" })
        local plantDescendantConnection
        local watchedPlantsFolder

        -- V15: the No Clip safety watchdog exists ONLY while No Clip is enabled.
        -- Generation invalidation cleanly stops an older worker without leaving
        -- an idle 0.75-second loop running in the background.
        local noClipWatchdogGeneration = 0
        local noClipWatchdogRunning = false

        local NoClipCard = card(2, 2, "NO CLIP", "Walk through plants in your garden.")
        local NoClipToggle

        local function getOwnPlot()
            local gardens = workspace:FindFirstChild("Gardens")
            if not gardens then
                return nil
            end

            -- Plots are named dynamically (Plot1, Plot2, Plot3, ...).
            -- Detect the local player's plot from the Owner / OwnerUserId attributes.
            for _, plot in ipairs(gardens:GetChildren()) do
                local owner = plot:GetAttribute("Owner")
                local ownerUserId = plot:GetAttribute("OwnerUserId")

                if tostring(owner or "") == LP.Name
                    or tonumber(ownerUserId) == LP.UserId then
                    return plot
                end
            end

            return nil
        end

        local function getOwnPlantsFolder()
            local ownPlot = getOwnPlot()
            if not ownPlot then
                return nil
            end

            return ownPlot:FindFirstChild("Plants")
        end

        local function setPlantNoclipClimbing(enabled)
            local humanoid = getHumanoid()
            if not humanoid then
                return
            end

            -- enabled=true means plant noclip is active, so disable Roblox's
            -- climbing state to stop the character from walking/jumping up trees.
            pcall(function()
                humanoid:SetStateEnabled(
                    Enum.HumanoidStateType.Climbing,
                    not enabled
                )
            end)

            if enabled and humanoid:GetState() == Enum.HumanoidStateType.Climbing then
                pcall(function()
                    humanoid:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
        end

        local function setPlantPartNoClip(part)
            if not part or not part:IsA("BasePart") then
                return
            end

            if collisionCache[part] == nil then
                collisionCache[part] = part.CanCollide
            end

            part.CanCollide = false
        end

        local function applyPlantNoClip()
            local plantsFolder = getOwnPlantsFolder()
            if not plantsFolder then
                return
            end

            for _, item in ipairs(plantsFolder:GetDescendants()) do
                if item:IsA("BasePart") then
                    setPlantPartNoClip(item)
                end
            end
        end

        local function stopWatchingPlants()
            if plantDescendantConnection then
                plantDescendantConnection:Disconnect()
                plantDescendantConnection = nil
            end
            watchedPlantsFolder = nil
        end

        local function watchPlantsFolder()
            local plantsFolder = getOwnPlantsFolder()
            if plantsFolder == watchedPlantsFolder and plantDescendantConnection then
                return
            end

            stopWatchingPlants()
            watchedPlantsFolder = plantsFolder

            if plantsFolder then
                plantDescendantConnection = TrackConnection(plantsFolder.DescendantAdded:Connect(function(item)
                    if State.NoClip and item:IsA("BasePart") then
                        task.defer(function()
                            if State.NoClip and item.Parent then
                                setPlantPartNoClip(item)
                            end
                        end)
                    end
                end))
            end
        end

        local function restoreCollisions()
            stopWatchingPlants()

            for part, oldValue in pairs(collisionCache) do
                if part and part.Parent and part:IsA("BasePart") then
                    pcall(function()
                        part.CanCollide = oldValue
                    end)
                end
            end

            table.clear(collisionCache)
        end

        local function stopNoClipWatchdog()
            noClipWatchdogGeneration += 1
            noClipWatchdogRunning = false
        end

        local function startNoClipWatchdog()
            if noClipWatchdogRunning
                or not State.NoClip
                or not ScoopHubRunAlive()
                or not SG.Parent then
                return
            end

            noClipWatchdogGeneration += 1
            local myGeneration = noClipWatchdogGeneration
            noClipWatchdogRunning = true

            task.spawn(function()
                -- DescendantAdded handles normal newly-created plant parts
                -- immediately. This watchdog is only the slow safety/repair path
                -- while No Clip is actually ON.
                while ScoopHubRunAlive()
                    and SG.Parent
                    and State.NoClip
                    and myGeneration == noClipWatchdogGeneration do

                    watchPlantsFolder()
                    applyPlantNoClip()
                    setPlantNoclipClimbing(true)

                    task.wait(0.75)
                end

                if myGeneration == noClipWatchdogGeneration then
                    noClipWatchdogRunning = false
                end
            end)
        end

        NoClipToggle = makeToggle(NoClipCard, State.NoClip, function(enabled)
            State.NoClip = enabled == true

            if State.NoClip then
                -- Apply immediately; do not wait for the watchdog's first cycle.
                watchPlantsFolder()
                applyPlantNoClip()
                setPlantNoclipClimbing(true)
                startNoClipWatchdog()
            else
                -- V15: OFF means zero recurring NoClip work.
                stopNoClipWatchdog()
                restoreCollisions()
                setPlantNoclipClimbing(false)
            end
        end)

        -- PERFORMANCE HISTORY:
        -- Older versions used RunService.Stepped and scanned every frame.
        -- V14 reduced that to a permanent 0.75s safety loop.
        -- V15 keeps the same 0.75s repair behavior ONLY while No Clip is enabled.

        -- Re-apply the humanoid setting after respawn while the toggle is on.
        TrackConnection(LP.CharacterAdded:Connect(function(character)
            if not State.NoClip then
                return
            end

            local humanoid = character:WaitForChild("Humanoid", 10)
            if humanoid then
                task.wait(.15)
                setPlantNoclipClimbing(true)
                watchPlantsFolder()
                applyPlantNoClip()
                startNoClipWatchdog()
            end
        end))

        -- State can persist if this UI is reloaded in the same session.
        if State.NoClip then
            task.defer(function()
                watchPlantsFolder()
                applyPlantNoClip()
                setPlantNoclipClimbing(true)
                startNoClipWatchdog()
            end)
        end

        RegisterScoopHubCleanup(function()
            stopNoClipWatchdog()
            restoreCollisions()
            setPlantNoclipClimbing(false)
        end)

        -- INFINITE JUMP ---------------------------------------------------------
        local InfiniteCard = card(1, 3, "INFINITE JUMP", "Jump again while already in the air.")
        local InfiniteToggle = makeToggle(InfiniteCard, State.InfiniteJump, function(enabled)
            State.InfiniteJump = enabled
        end)

        TrackConnection(UIS.JumpRequest:Connect(function()
            if not State.InfiniteJump then return end
            local humanoid = getHumanoid()
            if humanoid and humanoid.Health > 0 then
                pcall(function()
                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                end)
            end
        end))

        -- SERVER HOP ------------------------------------------------------------
        local ServerCard = card(2, 3, "SERVER HOPPER", "Teleport to another public server.")
        local serverHopBusy = false
        local ServerButton

        local function serverHop()
            if serverHopBusy then return end
            serverHopBusy = true
            ServerButton.Text = "SEARCHING..."

            task.spawn(function()
                local ok, result = pcall(function()
                    local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId)
                        .. "/servers/Public?sortOrder=Asc&limit=100"
                    return HttpService:JSONDecode(game:HttpGet(url))
                end)

                local choices = {}
                if ok and type(result) == "table" and type(result.data) == "table" then
                    for _, server in ipairs(result.data) do
                        if server.id
                            and server.id ~= game.JobId
                            and tonumber(server.playing)
                            and tonumber(server.maxPlayers)
                            and server.playing < server.maxPlayers then
                            table.insert(choices, server.id)
                        end
                    end
                end

                if #choices > 0 then
                    local target = choices[math.random(1, #choices)]
                    queueScoopHubAfterTeleport()
                    pcall(function()
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, target, LP)
                    end)
                else
                    ServerButton.Text = "NO SERVER FOUND"
                    task.wait(1.2)
                    ServerButton.Text = "SERVER HOP"
                    serverHopBusy = false
                end
            end)
        end

        ServerButton = makeAction(ServerCard, "SERVER HOP", serverHop)

        -- SET FPS ---------------------------------------------------------------
        local FPSCard = card(1, 4, "SET FPS", "Choose your target frame rate.")
        local FPSButton = C(N("TextButton", {
            Text = State.FPS,
            AutoButtonColor = false,
            Font = T.Font,
            TextSize = 10,
            TextColor3 = T.White,
            TextXAlignment = Enum.TextXAlignment.Left,
            BackgroundColor3 = T.Input,
            BorderSizePixel = 0,
            Position = UDim2.new(0, 9, 0, 36),
            Size = UDim2.new(1, -18, 0, 22),
            ZIndex = 15,
        }, FPSCard), 5)
        N("UIPadding", { PaddingLeft = UDim.new(0, 8) }, FPSButton)
        S(FPSButton, T.Line, .72, 1)

        local Chevron = label(
            FPSButton,
            "▼",
            UDim2.new(1, -20, 0, 0),
            UDim2.fromOffset(14, 22),
            8,
            T.Muted,
            T.Font,
            Enum.TextXAlignment.Center
        )
        Chevron.ZIndex = 16

        local FPSOptions = { "10", "15", "30", "60", "120", "inf" }
        local FPSDropdown = C(N("Frame", {
            Visible = false,
            BackgroundColor3 = T.Surface2,
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(120, (#FPSOptions * 24) + 6),
            ZIndex = 100,
        }, Page), 6)
        S(FPSDropdown, T.Red, .15, 1)

        local FPSList = N("Frame", {
            BackgroundTransparency = 1,
            Position = UDim2.fromOffset(3, 3),
            Size = UDim2.new(1, -6, 1, -6),
            ZIndex = 101,
        }, FPSDropdown)
        N("UIListLayout", { Padding = UDim.new(0, 0) }, FPSList)

        local function applyFPS(value)
            State.FPS = tostring(value)
            FPSButton.Text = State.FPS

            local cap = State.FPS == "inf" and 9999 or tonumber(State.FPS)
            local setter = setfpscap
            if type(setter) == "function" and cap then
                -- Reset the executor's previous FPS cap first.
                -- This fixes the common case where 15 FPS applies correctly,
                -- but changing upward to 30/60/120 stays stuck at the old cap.
                --
                -- setfpscap(0) is the normal "uncap/reset" path on supported
                -- executors. 9999 is used as a fallback/high reset as well.
                pcall(setter, 0)
                pcall(setter, 9999)

                -- Give the executor one scheduler step to release the old limiter,
                -- then apply the user's actual selected value.
                task.wait()

                if State.FPS == "inf" then
                    pcall(setter, 9999)
                else
                    pcall(setter, cap)
                end
            end
        end

        for _, option in ipairs(FPSOptions) do
            local row = N("TextButton", {
                Text = option,
                AutoButtonColor = false,
                Font = T.Body,
                TextSize = 10,
                TextColor3 = T.White,
                TextXAlignment = Enum.TextXAlignment.Left,
                BackgroundColor3 = T.Surface2,
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                Size = UDim2.new(1, 0, 0, 24),
                ZIndex = 102,
            }, FPSList)
            N("UIPadding", { PaddingLeft = UDim.new(0, 8) }, row)

            row.MouseEnter:Connect(function()
                row.BackgroundColor3 = T.RedDark
            end)
            row.MouseLeave:Connect(function()
                row.BackgroundColor3 = T.Surface2
            end)
            row.Activated:Connect(function()
                FPSDropdown.Visible = false
                applyFPS(option)
            end)
        end

        local function positionFPSDropdown()
            local pagePos = Page.AbsolutePosition
            local buttonPos = FPSButton.AbsolutePosition
            local buttonSize = FPSButton.AbsoluteSize
            local dropdownHeight = FPSDropdown.AbsoluteSize.Y
            local pageBottom = pagePos.Y + Page.AbsoluteSize.Y

            local x = buttonPos.X - pagePos.X
            local belowY = buttonPos.Y - pagePos.Y + buttonSize.Y + 3
            local aboveY = buttonPos.Y - pagePos.Y - dropdownHeight - 3
            local y = ((pagePos.Y + belowY + dropdownHeight) <= pageBottom) and belowY or aboveY

            FPSDropdown.Position = UDim2.fromOffset(x, math.max(0, y))
            FPSDropdown.Size = UDim2.fromOffset(math.max(120, buttonSize.X), (#FPSOptions * 24) + 6)
        end

        FPSButton.Activated:Connect(function()
            FPSDropdown.Visible = not FPSDropdown.Visible
            if FPSDropdown.Visible then
                positionFPSDropdown()
            end
        end)

        -- REJOIN ----------------------------------------------------------------
        local RejoinCard = card(2, 4, "REJOIN SERVER", "Reconnect to the current server.")
        makeAction(RejoinCard, "REJOIN", function()
            queueScoopHubAfterTeleport()
            pcall(function()
                if game.JobId and game.JobId ~= "" then
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP)
                else
                    TeleportService:Teleport(game.PlaceId, LP)
                end
            end)
        end)

        -- CLEANUP ---------------------------------------------------------------
        local cleanupInitial = false
        if _G.ScoopHubAutoBuyPetAPI and _G.ScoopHubAutoBuyPetAPI.IsCleanupEnabled then
            pcall(function()
                cleanupInitial = _G.ScoopHubAutoBuyPetAPI.IsCleanupEnabled() == true
            end)
        end

        local CleanupCard = card(1, 5, "CLEANUP", "FPS cleanup. Your garden stays visible as plain colors.")
        local CleanupToggle = makeToggle(CleanupCard, cleanupInitial, function(enabled)
            if _G.ScoopHubAutoBuyPetAPI and _G.ScoopHubAutoBuyPetAPI.SetCleanup then
                pcall(function()
                    _G.ScoopHubAutoBuyPetAPI.SetCleanup(enabled)
                end)
            end
        end)

        -- V20 PERFORMANCE:
        -- Cleanup is only mirrored into Misc while Misc is actually visible.
        -- The real cleanup system remains fully independent of this presentation.
        do
            local CleanupMirrorGeneration = 0

            local function RefreshCleanupMirror()
                if _G.ScoopHubAutoBuyPetAPI
                    and _G.ScoopHubAutoBuyPetAPI.IsCleanupEnabled then

                    local ok, value = pcall(function()
                        return _G.ScoopHubAutoBuyPetAPI.IsCleanupEnabled()
                    end)

                    if ok
                        and CleanupToggle:Get() ~= (value == true) then

                        CleanupToggle:Set(
                            value == true,
                            false
                        )
                    end
                end
            end

            local function RestartCleanupMirrorWorker()
                CleanupMirrorGeneration += 1
                local myGeneration = CleanupMirrorGeneration

                if not Page.Visible then
                    return
                end

                RefreshCleanupMirror()

                task.spawn(function()
                    while ScoopHubRunAlive()
                        and SG.Parent
                        and Page.Parent
                        and Page.Visible
                        and CleanupMirrorGeneration == myGeneration do

                        task.wait(0.5)

                        if not ScoopHubRunAlive()
                            or not SG.Parent
                            or not Page.Parent
                            or not Page.Visible
                            or CleanupMirrorGeneration ~= myGeneration then
                            break
                        end

                        RefreshCleanupMirror()
                    end
                end)
            end

            TrackConnection(
                Page:GetPropertyChangedSignal("Visible"):Connect(
                    RestartCleanupMirrorWorker
                )
            )

            RestartCleanupMirrorWorker()
        end

        -- REMOVE OTHER GARDENS --------------------------------------------------
        local hiddenFolder = ReplicatedStorage:FindFirstChild("ScoopHubHiddenGardens")
        if not hiddenFolder then
            hiddenFolder = Instance.new("Folder")
            hiddenFolder.Name = "ScoopHubHiddenGardens"
            hiddenFolder.Parent = ReplicatedStorage
        end

        local hiddenGardens = {}
        local gardenAddedConnection
        local RemoveGardenCard = card(2, 5, "REMOVE OTHER GARDENS", "Hide other plots only. Your plot stays.")
        local RemoveGardenToggle

        local function getOwnPlotName()
            local plotId = LP:GetAttribute("PlotId")
            if plotId == nil then
                return nil
            end
            return "Plot" .. tostring(plotId)
        end

        local function hideOtherGardens()
            local gardens = Workspace:FindFirstChild("Gardens")
            local ownPlotName = getOwnPlotName()
            if not gardens or not ownPlotName then
                return false
            end

            for _, plot in ipairs(gardens:GetChildren()) do
                if plot.Name ~= ownPlotName and plot.Name:match("^Plot") then
                    hiddenGardens[plot] = gardens
                    plot.Parent = hiddenFolder
                end
            end

            return true
        end

        local function restoreOtherGardens()
            if gardenAddedConnection then
                gardenAddedConnection:Disconnect()
                gardenAddedConnection = nil
            end

            local gardens = Workspace:FindFirstChild("Gardens")
            if not gardens then
                gardens = Instance.new("Folder")
                gardens.Name = "Gardens"
                gardens.Parent = Workspace
            end

            for plot in pairs(hiddenGardens) do
                if plot and plot.Parent == hiddenFolder then
                    plot.Parent = gardens
                end
                hiddenGardens[plot] = nil
            end
        end

        local function setRemoveOtherGardens(enabled)
            State.RemoveOtherGardens = enabled == true

            if not State.RemoveOtherGardens then
                restoreOtherGardens()
                return true
            end

            if not hideOtherGardens() then
                State.RemoveOtherGardens = false
                return false
            end

            local gardens = Workspace:FindFirstChild("Gardens")
            if gardens then
                gardenAddedConnection = TrackConnection(gardens.ChildAdded:Connect(function(plot)
                    if not State.RemoveOtherGardens then return end
                    task.defer(function()
                        local ownPlotName = getOwnPlotName()
                        if ownPlotName
                            and plot.Parent == gardens
                            and plot.Name ~= ownPlotName
                            and plot.Name:match("^Plot") then
                            hiddenGardens[plot] = gardens
                            plot.Parent = hiddenFolder
                        end
                    end)
                end))
            end

            return true
        end

        RemoveGardenToggle = makeToggle(RemoveGardenCard, State.RemoveOtherGardens, function(enabled)
            local ok = setRemoveOtherGardens(enabled)
            if not ok then
                RemoveGardenToggle:Set(false, false)
            end
        end)

        if State.RemoveOtherGardens then
            local ok = setRemoveOtherGardens(true)
            if not ok then
                RemoveGardenToggle:Set(false, false)
            end
        end


        -- BACKPACK VALUE ESP ----------------------------------------------------
        -- Display-only view over Mail Fruits' existing authoritative seller-value
        -- cache. Backpack ESP never starts its own seller scan, so equipping or
        -- unequipping a fruit cannot trigger competing GetFruitBid refreshes.
        -- The exact InventoryController slot -> fruit-instance mapping is preserved
        -- so duplicate fruits with identical names/weights still get the right value.
        local function createBackpackValueRuntime()
            local previous = rawget(_G, "ScoopHubBackpackValueESP")
            if type(previous) == "table" and type(previous.Stop) == "function" then
                pcall(previous.Stop)
            end

            local playerGui = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui")
            local backpack = LP:FindFirstChild("Backpack") or LP:WaitForChild("Backpack")
            local VALUE_COLOR = Color3.fromRGB(255, 199, 74)
            local VALUE_STROKE = Color3.fromRGB(0, 0, 0)
            local SLOT_LABEL_NAME = "ScoopHubFruitValue"
            local TOTAL_LABEL_NAME = "ScoopHubFruitTotalValue"

            local runtime = {
                Enabled = false,
                Connections = {},
                RefreshScheduled = false,
                Generation = 0,
            }

            local api = {}
            local refreshVisuals

            local function track(connection)
                runtime.Connections[#runtime.Connections + 1] = connection
                TrackConnection(connection)
                return connection
            end

            local function disconnectRuntimeConnections()
                for _, connection in ipairs(runtime.Connections) do
                    pcall(function()
                        connection:Disconnect()
                    end)
                end
                table.clear(runtime.Connections)
            end

            local function destroyOverlayLabels()
                for _, object in ipairs(playerGui:GetDescendants()) do
                    if object.Name == SLOT_LABEL_NAME or object.Name == TOTAL_LABEL_NAME then
                        pcall(function()
                            object:Destroy()
                        end)
                    end
                end
            end

            local function isHarvestedFruit(item)
                if not item or typeof(item) ~= "Instance" then
                    return false
                end

                if item:GetAttribute("HarvestedFruit") ~= true then
                    return false
                end

                return item:GetAttribute("Id") ~= nil
                    and (item:GetAttribute("FruitName") or item:GetAttribute("Fruit")) ~= nil
                    and tonumber(item:GetAttribute("Weight")) ~= nil
            end

            local function getInventoryParts()
                local backpackGui = playerGui:FindFirstChild("BackpackGui")
                local backpackFrame = backpackGui and backpackGui:FindFirstChild("Backpack")
                local inventory = backpackFrame and backpackFrame:FindFirstChild("Inventory")
                local scrolling = inventory and inventory:FindFirstChild("ScrollingFrame")
                local grid = scrolling and scrolling:FindFirstChild("UIGridFrame")
                local favorite = inventory and inventory:FindFirstChild("FavoriteFilter")
                local hotbar = backpackFrame and backpackFrame:FindFirstChild("Hotbar")
                return inventory, grid, favorite, hotbar
            end

            local function collectUpvalues(fn)
                local output = {}

                if type(getupvalues) == "function" then
                    local ok, values = pcall(getupvalues, fn)
                    if ok and type(values) == "table" then
                        output[#output + 1] = values
                    end
                end

                if debug and type(debug.getupvalues) == "function" then
                    local ok, values = pcall(debug.getupvalues, fn)
                    if ok and type(values) == "table" then
                        output[#output + 1] = values
                    end
                end

                return output
            end

            local function fruitFromSlot(slot)
                if not slot or not slot:IsA("GuiButton") or type(getconnections) ~= "function" then
                    return nil
                end

                local ok, connections = pcall(getconnections, slot.MouseButton1Click)
                if not ok or type(connections) ~= "table" then
                    return nil
                end

                for _, connection in ipairs(connections) do
                    local fn
                    pcall(function()
                        fn = connection.Function
                    end)

                    if type(fn) == "function" then
                        for _, values in ipairs(collectUpvalues(fn)) do
                            for _, value in pairs(values) do
                                if type(value) == "table" then
                                    local frame = rawget(value, "Frame")
                                    local tool = rawget(value, "Tool")

                                    if frame == slot
                                        and typeof(tool) == "Instance"
                                        and isHarvestedFruit(tool) then
                                        return tool
                                    end
                                end
                            end
                        end
                    end
                end

                return nil
            end

            local function trimZeros(text)
                return tostring(text)
                    :gsub("(%..-)0+$", "%1")
                    :gsub("%.$", "")
            end

            local function compactNumber(value)
                value = tonumber(value) or 0
                local absolute = math.abs(value)
                local divisor = 1
                local suffix = ""

                if absolute >= 1e15 then
                    divisor, suffix = 1e15, "Q"
                elseif absolute >= 1e12 then
                    divisor, suffix = 1e12, "T"
                elseif absolute >= 1e9 then
                    divisor, suffix = 1e9, "B"
                elseif absolute >= 1e6 then
                    divisor, suffix = 1e6, "M"
                elseif absolute >= 1e3 then
                    divisor, suffix = 1e3, "K"
                end

                if divisor == 1 then
                    return tostring(math.floor(value + 0.5))
                end

                return trimZeros(string.format("%.2f", value / divisor)) .. suffix
            end

            local function formatMoney(value)
                return "$" .. compactNumber(value)
            end

            local function getFruitValue(item)
                if not isHarvestedFruit(item) then
                    return nil
                end

                -- Mail Fruits is the single owner of seller quotes. Only display an
                -- authoritative cached GetFruitBid value here; never substitute the
                -- local calculator while Mail is still resolving the fruit.
                local bridge = _G.ScoopHubMailFruitInventoryAPI
                local id = tostring(item:GetAttribute("Id"))
                local cache = bridge and bridge.FruitValueCache
                local cached = cache and cache[id]
                local cachedValue = cached and tonumber(cached.Value)

                if cachedValue ~= nil then
                    return math.floor(cachedValue)
                end

                return nil
            end

            local function ensureSlotValueLabel(slot)
                local labelObject = slot:FindFirstChild(SLOT_LABEL_NAME)
                if labelObject and not labelObject:IsA("TextLabel") then
                    labelObject:Destroy()
                    labelObject = nil
                end

                if not labelObject then
                    labelObject = Instance.new("TextLabel")
                    labelObject.Name = SLOT_LABEL_NAME
                    labelObject.BackgroundTransparency = 1
                    labelObject.BorderSizePixel = 0
                    labelObject.Position = UDim2.new(0, 1, 0, 0)
                    labelObject.Size = UDim2.new(1, -2, 0, 18)
                    labelObject.Font = Enum.Font.GothamBold
                    labelObject.TextSize = 14
                    labelObject.TextColor3 = VALUE_COLOR
                    labelObject.TextStrokeColor3 = VALUE_STROKE
                    labelObject.TextStrokeTransparency = 0.25
                    labelObject.TextXAlignment = Enum.TextXAlignment.Center
                    labelObject.TextYAlignment = Enum.TextYAlignment.Center
                    labelObject.TextTruncate = Enum.TextTruncate.AtEnd
                    labelObject.ZIndex = 12
                    labelObject.Parent = slot
                else
                    labelObject.TextColor3 = VALUE_COLOR
                end

                return labelObject
            end

            local function ensureTotalLabel(inventory, favorite)
                if not inventory or not favorite then
                    return nil
                end

                local totalLabel = inventory:FindFirstChild(TOTAL_LABEL_NAME)
                if totalLabel and not totalLabel:IsA("TextLabel") then
                    totalLabel:Destroy()
                    totalLabel = nil
                end

                if not totalLabel then
                    totalLabel = Instance.new("TextLabel")
                    totalLabel.Name = TOTAL_LABEL_NAME
                    totalLabel.BackgroundTransparency = 1
                    totalLabel.BorderSizePixel = 0
                    totalLabel.AnchorPoint = Vector2.new(1, 0)
                    totalLabel.Size = UDim2.fromOffset(125, 30)
                    totalLabel.Font = Enum.Font.GothamBold
                    totalLabel.TextSize = 12
                    totalLabel.TextColor3 = VALUE_COLOR
                    totalLabel.TextStrokeColor3 = VALUE_STROKE
                    totalLabel.TextStrokeTransparency = 0.35
                    totalLabel.TextXAlignment = Enum.TextXAlignment.Right
                    totalLabel.TextYAlignment = Enum.TextYAlignment.Center
                    totalLabel.ZIndex = math.max(2, favorite.ZIndex + 1)
                    totalLabel.Parent = inventory
                else
                    totalLabel.TextColor3 = VALUE_COLOR
                end

                totalLabel.Position = UDim2.new(
                    favorite.Position.X.Scale,
                    favorite.Position.X.Offset - 8,
                    favorite.Position.Y.Scale,
                    favorite.Position.Y.Offset
                )

                return totalLabel
            end

            local function collectHarvestedFruits()
                local list = {}
                local seen = {}

                local function scan(container)
                    if not container then return end
                    for _, item in ipairs(container:GetChildren()) do
                        if isHarvestedFruit(item) then
                            local id = tostring(item:GetAttribute("Id"))
                            if not seen[id] then
                                seen[id] = true
                                list[#list + 1] = item
                            end
                        end
                    end
                end

                scan(backpack)
                scan(LP.Character)
                return list
            end

            local function renderFruitSlots(root)
                if not root then return end

                local candidates = { root }
                for _, object in ipairs(root:GetDescendants()) do
                    candidates[#candidates + 1] = object
                end

                for _, slot in ipairs(candidates) do
                    if slot:IsA("GuiButton") then
                        local fruit = fruitFromSlot(slot)
                        local existing = slot:FindFirstChild(SLOT_LABEL_NAME)

                        if fruit then
                            local valueLabel = ensureSlotValueLabel(slot)
                            local value = getFruitValue(fruit)
                            valueLabel.Text = value ~= nil and formatMoney(value) or ""
                            valueLabel.Visible = runtime.Enabled
                        elseif existing then
                            existing:Destroy()
                        end
                    end
                end
            end

            refreshVisuals = function()
                if not runtime.Enabled then
                    return
                end

                local inventory, grid, favorite, hotbar = getInventoryParts()
                if not inventory and not hotbar then
                    return
                end

                local totalLabel = inventory and ensureTotalLabel(inventory, favorite) or nil

                if grid then
                    renderFruitSlots(grid)
                end
                if hotbar then
                    renderFruitSlots(hotbar)
                end

                local total = 0
                local unresolved = 0
                for _, fruit in ipairs(collectHarvestedFruits()) do
                    local value = getFruitValue(fruit)
                    if value ~= nil then
                        total += value
                    else
                        unresolved += 1
                    end
                end

                if totalLabel then
                    totalLabel.Text = unresolved > 0
                        and "Total: ..."
                        or ("Total: " .. formatMoney(total))
                    totalLabel.Visible = true
                end
            end

            local function scheduleRefresh(delaySeconds)
                if not runtime.Enabled then
                    return
                end

                if runtime.RefreshScheduled then
                    return
                end

                runtime.RefreshScheduled = true
                task.delay(delaySeconds or 0.12, function()
                    runtime.RefreshScheduled = false
                    if runtime.Enabled then
                        pcall(refreshVisuals)
                    end
                end)
            end

            local function watchCharacter(character)
                if not character then return end
                track(character.ChildAdded:Connect(function()
                    scheduleRefresh(0.18)
                end))
                track(character.ChildRemoved:Connect(function()
                    scheduleRefresh(0.18)
                end))
            end

            function api.Start()
                if runtime.Enabled then
                    pcall(refreshVisuals)
                    return true
                end

                if type(getconnections) ~= "function" then
                    warn("[ScoopHub] Backpack Value ESP requires getconnections support.")
                    return false
                end

                runtime.Enabled = true
                runtime.Generation += 1
                local generation = runtime.Generation

                track(backpack.ChildAdded:Connect(function()
                    scheduleRefresh(0.18)
                end))
                track(backpack.ChildRemoved:Connect(function()
                    scheduleRefresh(0.18)
                end))

                track(LP.CharacterAdded:Connect(function(character)
                    watchCharacter(character)
                    scheduleRefresh(0.4)
                end))
                watchCharacter(LP.Character)

                track(playerGui.DescendantAdded:Connect(function(object)
                    if object.Name == "UIGridFrame"
                        or object.Name == "Hotbar"
                        or object.Name == "FavoriteFilter"
                        or object.Name == "ToolName"
                        or object.Name == "ToolCount" then
                        scheduleRefresh(0.15)
                    end
                end))

                scheduleRefresh(0.15)

                -- Lightweight visible-inventory reconciliation only redraws labels.
                -- Mail Fruits independently owns initial/new-fruit/price-reset scans.
                task.spawn(function()
                    while runtime.Enabled
                        and runtime.Generation == generation
                        and ScoopHubRunAlive()
                        and SG.Parent do
                        local inventory, _, _, hotbar = getInventoryParts()
                        local inventoryVisible = inventory and inventory.Visible
                        local hotbarVisible = hotbar and hotbar.Visible

                        if inventoryVisible or hotbarVisible then
                            pcall(refreshVisuals)
                            task.wait(1)
                        else
                            task.wait(2)
                        end
                    end
                end)

                return true
            end

            function api.Stop()
                runtime.Enabled = false
                runtime.Generation += 1
                runtime.RefreshScheduled = false
                disconnectRuntimeConnections()
                destroyOverlayLabels()
            end

            function api.Refresh()
                if runtime.Enabled then
                    scheduleRefresh(0)
                end
            end

            function api.IsEnabled()
                return runtime.Enabled == true
            end

            _G.ScoopHubBackpackValueESP = api
            return api
        end

        local BackpackValueRuntime = createBackpackValueRuntime()
        RegisterScoopHubCleanup(function()
            BackpackValueRuntime.Stop()
        end)

        local BackpackValueCard = card(2, 6, "BACKPACK VALUE ESP", "Show live Sheckles values in Backpack / Hotbar.")
        local BackpackValueToggle
        BackpackValueToggle = makeToggle(BackpackValueCard, false, function(enabled)
            if enabled then
                local ok = BackpackValueRuntime.Start()
                State.BackpackValueESP = ok == true
                if not ok then
                    BackpackValueToggle:Set(false, false)
                end
            else
                State.BackpackValueESP = false
                BackpackValueRuntime.Stop()
            end
        end)


        -- WILD PET ESP ----------------------------------------------------------
        -- Presentation control lives in Misc; the actual label engine remains
        -- owned by Auto Buy Pet so no pet logic is duplicated here.
        local WildPetEspCard = card(1, 6, "WILD PET ESP", "Show Name / Size / Rarity above wild pets.")
        local WildPetEspToggle
        WildPetEspToggle = makeToggle(WildPetEspCard, false, function(enabled)
            local api = _G.ScoopHubAutoBuyPetAPI
            if api and type(api.SetWildPetESP) == "function" then
                local ok = pcall(api.SetWildPetESP, enabled == true)
                if not ok then
                    WildPetEspToggle:Set(false, false)
                end
            else
                WildPetEspToggle:Set(false, false)
            end
        end)

        -- ESP intentionally starts OFF on every execution, regardless of prior
        -- Misc/config state. This also clears any stale labels from an older run.
        if _G.ScoopHubAutoBuyPetAPI and type(_G.ScoopHubAutoBuyPetAPI.SetWildPetESP) == "function" then
            pcall(_G.ScoopHubAutoBuyPetAPI.SetWildPetESP, false)
        end

        -- GARDEN ESP ------------------------------------------------------------
        -- Full-width Misc card. The runtime is completely idle while disabled or
        -- while either multi-select has no usable selection.
        local GardenESPFeature = (function()
            local feature = {}
            local runtime = {
                Enabled = false,
                FruitAll = false,
                MutationAll = true,
                SelectedFruits = {},
                SelectedMutations = {},
                KnownFruits = {},
                KnownMutations = {},
                Labels = {},
                Connections = {},
                WorkerGeneration = 0,
                ModulesReady = false,
                ModulesFailed = false,
                Modules = {},
                ModuleCache = {},
                ResolveCache = {},
                MultiCache = {},
                MutationCache = {},
                SyncCache = {},
                SellNorm = {},
                SingleHarvest = {},
                LastData = {},
            }

            local STATIC_MUTATIONS = {
                "Normal", "Gold", "Rainbow", "Wet", "Chilled", "Frozen",
                "Shocked", "Choc", "Moonlit", "Bloodlit", "Celestial",
                "Zombified", "Plasma", "Voidtouched", "Pollinated", "Twisted",
                "Disco", "Windstruck", "Dawnbound", "Electric", "Burnt",
                "HoneyGlazed", "Cooked", "Molten", "Sundried", "Wilted",
                "Alienlike",
            }

            for _, mutationName in ipairs(STATIC_MUTATIONS) do
                runtime.KnownMutations[mutationName] = true
            end

            local worldData = _G.ScoopHubWorldData
            local currentWorld = worldData and worldData.Current
            for _, seedName in ipairs(currentWorld and currentWorld.Seeds or {}) do
                local cleanName = tostring(seedName or "")
                    :gsub("%s*[Ss]eed%s*$", "")
                    :gsub("^%s+", "")
                    :gsub("%s+$", "")
                if cleanName ~= "" then
                    runtime.KnownFruits[cleanName] = true
                end
            end

            local function sortedKeys(set)
                local output = {}
                for key, selected in pairs(set or {}) do
                    if selected == true then
                        output[#output + 1] = tostring(key)
                    end
                end
                table.sort(output, function(a, b)
                    return string.lower(a) < string.lower(b)
                end)
                return output
            end

            local function selectedCount(set)
                local count = 0
                for _, selected in pairs(set or {}) do
                    if selected == true then
                        count += 1
                    end
                end
                return count
            end

            local function clearSet(set)
                for key in pairs(set) do
                    set[key] = nil
                end
            end

            local function copyListIntoSet(list, destination, known)
                clearSet(destination)
                if type(list) ~= "table" then
                    return
                end
                for _, value in ipairs(list) do
                    local textValue = tostring(value or "")
                    if textValue ~= "" then
                        destination[textValue] = true
                        if known then
                            known[textValue] = true
                        end
                    end
                end
            end

            local function destroyLabels()
                for key, record in pairs(runtime.Labels) do
                    if record.Billboard and record.Billboard.Parent then
                        pcall(function()
                            record.Billboard:Destroy()
                        end)
                    end
                    runtime.Labels[key] = nil
                end
            end

            local labelFolder = LP:FindFirstChildOfClass("PlayerGui")
                and LP:FindFirstChildOfClass("PlayerGui"):FindFirstChild("ScoopHubGardenESP")
            if labelFolder then
                labelFolder:Destroy()
                labelFolder = nil
            end

            local function ensureLabelFolder()
                if labelFolder and labelFolder.Parent then
                    return labelFolder
                end

                local playerGui = LP:FindFirstChildOfClass("PlayerGui")
                    or LP:WaitForChild("PlayerGui", 10)
                if not playerGui then
                    return nil
                end

                local stale = playerGui:FindFirstChild("ScoopHubGardenESP")
                if stale then
                    stale:Destroy()
                end

                labelFolder = Instance.new("Folder")
                labelFolder.Name = "ScoopHubGardenESP"
                labelFolder.Parent = playerGui
                return labelFolder
            end

            local function rgbHex(color)
                return string.format(
                    "#%02X%02X%02X",
                    math.floor(color.R * 255 + 0.5),
                    math.floor(color.G * 255 + 0.5),
                    math.floor(color.B * 255 + 0.5)
                )
            end

            local function escapeRichText(value)
                return tostring(value or "")
                    :gsub("&", "&amp;")
                    :gsub("<", "&lt;")
                    :gsub(">", "&gt;")
                    :gsub('"', "&quot;")
                    :gsub("'", "&apos;")
            end

            local function formatCompact(value)
                value = tonumber(value) or 0
                local result

                if value >= 1e24 then
                    result = string.format("%.2fSp", value / 1e24)
                elseif value >= 1e21 then
                    result = string.format("%.2fSx", value / 1e21)
                elseif value >= 1e18 then
                    result = string.format("%.2fQi", value / 1e18)
                elseif value >= 1e15 then
                    result = string.format("%.2fQ", value / 1e15)
                elseif value >= 1e12 then
                    result = string.format("%.2fT", value / 1e12)
                elseif value >= 1e9 then
                    result = string.format("%.2fB", value / 1e9)
                elseif value >= 1e6 then
                    result = string.format("%.2fM", value / 1e6)
                elseif value >= 1e3 then
                    result = string.format("%.2fK", value / 1e3)
                else
                    return tostring(math.floor(value))
                end

                return result
                    :gsub("%.00", "")
                    :gsub("(%.[0-9])0", "%1")
            end

            local function formatKG(value)
                value = tonumber(value) or 0

                if value >= 1e6 then
                    return (string.format("%.2fM", value / 1e6)
                        :gsub("%.00", "")
                        :gsub("(%.[0-9])0", "%1")) .. "kg"
                elseif value >= 1e3 then
                    return (string.format("%.2fK", value / 1e3)
                        :gsub("%.00", "")
                        :gsub("(%.[0-9])0", "%1")) .. "kg"
                end

                return string.format("%.1f", value):gsub("%.0$", "") .. "kg"
            end

            local function buildESPText(data)
                return string.format(
                    '<font color="%s"><b>%s</b></font> <font color="%s">[%s]</font> <font color="%s">%s</font> <font color="%s">•</font> <font color="%s"><b>%s</b></font>',
                    rgbHex(T.White),
                    escapeRichText(data.Name),
                    rgbHex(T.Text),
                    escapeRichText(data.Mutation or "Normal"),
                    rgbHex(T.Muted),
                    escapeRichText(formatKG(data.KG)),
                    rgbHex(T.Muted),
                    rgbHex(Color3.fromRGB(255, 199, 74)),
                    escapeRichText(formatCompact(data.Value))
                )
            end

            local function findAnchorAndCenterOffset(object)
                if not object or not object.Parent then
                    return nil, Vector3.zero
                end

                -- BasePart fruits are already centered on their own part.
                if object:IsA("BasePart") then
                    return object, Vector3.zero
                end

                -- For Models, use any stable BasePart as the Billboard Adornee but
                -- offset the Billboard to the model's real bounding-box CENTER.
                -- This keeps the ESP literally inside/centered on the fruit instead
                -- of floating above it.
                if object:IsA("Model") then
                    local anchor = object.PrimaryPart
                        or object:FindFirstChildWhichIsA("BasePart", true)

                    if not anchor then
                        return nil, Vector3.zero
                    end

                    local ok, boxCFrame = pcall(function()
                        return object:GetBoundingBox()
                    end)

                    if ok and boxCFrame then
                        return anchor, boxCFrame.Position - anchor.Position
                    end

                    return anchor, Vector3.zero
                end

                -- Fallback for unusual fruit containers: choose the part closest
                -- to the container's average part position rather than the highest
                -- part, so the label still sits near the visual center.
                local parts = {}
                local sum = Vector3.zero

                for _, descendant in ipairs(object:GetDescendants()) do
                    if descendant:IsA("BasePart") then
                        parts[#parts + 1] = descendant
                        sum += descendant.Position
                    end
                end

                if #parts == 0 then
                    return nil, Vector3.zero
                end

                local center = sum / #parts
                local best = parts[1]
                local bestDistance = (best.Position - center).Magnitude

                for index = 2, #parts do
                    local part = parts[index]
                    local distance = (part.Position - center).Magnitude
                    if distance < bestDistance then
                        best = part
                        bestDistance = distance
                    end
                end

                return best, center - best.Position
            end

            local function ensureLabel(data)
                local record = runtime.Labels[data.Key]
                if record and record.Billboard and record.Billboard.Parent then
                    return record
                end

                local folder = ensureLabelFolder()
                if not folder then
                    return nil
                end

                local mobile = UIS.TouchEnabled and not UIS.KeyboardEnabled
                local billboard = Instance.new("BillboardGui")
                billboard.Name = "GardenESP_" .. tostring(data.Key)
                billboard.Size = UDim2.fromOffset(mobile and 250 or 310, mobile and 20 or 24)
                billboard.StudsOffsetWorldSpace = Vector3.zero
                billboard.AlwaysOnTop = true
                billboard.LightInfluence = 0
                pcall(function()
                    billboard.MaxDistance = 135
                end)
                billboard.Parent = folder

                local textObject = Instance.new("TextLabel")
                textObject.Name = "Text"
                textObject.Size = UDim2.fromScale(1, 1)
                textObject.BackgroundTransparency = 1
                textObject.BorderSizePixel = 0
                textObject.RichText = true
                textObject.Text = ""
                textObject.TextColor3 = T.White
                textObject.TextSize = mobile and 10 or 12
                textObject.TextStrokeColor3 = Color3.new(0, 0, 0)
                textObject.TextStrokeTransparency = 0.45
                textObject.Font = Enum.Font.Gotham
                textObject.TextXAlignment = Enum.TextXAlignment.Center
                textObject.TextYAlignment = Enum.TextYAlignment.Center
                textObject.Parent = billboard

                record = {
                    Billboard = billboard,
                    Text = textObject,
                    Anchor = nil,
                }
                runtime.Labels[data.Key] = record
                return record
            end

            local function updateLabel(data)
                local anchor, centerOffset = findAnchorAndCenterOffset(data.Object)
                if not anchor then
                    return false
                end

                local record = ensureLabel(data)
                if not record then
                    return false
                end

                record.Anchor = anchor
                record.Billboard.Adornee = anchor
                record.Billboard.StudsOffsetWorldSpace = centerOffset
                record.Billboard.Enabled = true
                record.Text.Text = buildESPText(data)
                return true
            end

            local function hasUsableSelection()
                local fruitOK = runtime.FruitAll or selectedCount(runtime.SelectedFruits) > 0
                local mutationOK = runtime.MutationAll or selectedCount(runtime.SelectedMutations) > 0
                return fruitOK and mutationOK
            end

            local function compactFruitName(value)
                return tostring(value or "")
                    :gsub("%s*[Ss]eed%s*$", "")
                    :lower()
                    :gsub("[^%w]", "")
            end

            local function fruitSelectionMatches(value)
                if runtime.FruitAll then
                    return true
                end

                if runtime.SelectedFruits[tostring(value or "")] == true then
                    return true
                end

                local actual = compactFruitName(value)
                if actual == "" then
                    return false
                end

                for selectedName, selected in pairs(runtime.SelectedFruits) do
                    if selected and compactFruitName(selectedName) == actual then
                        return true
                    end
                end

                return false
            end

            local function mutationSelectionMatches(value)
                if runtime.MutationAll then
                    return true
                end

                local actual = string.lower(tostring(value or "Normal"))
                for selectedName, selected in pairs(runtime.SelectedMutations) do
                    if selected and string.lower(tostring(selectedName)) == actual then
                        return true
                    end
                end
                return false
            end

            local function shouldShow(data)
                if not runtime.Enabled then
                    return false
                end

                return fruitSelectionMatches(data.Name)
                    and mutationSelectionMatches(data.Mutation)
            end

            local function applyData(dataList)
                runtime.LastData = dataList or {}
                local seen = {}

                if runtime.Enabled and hasUsableSelection() then
                    for _, data in ipairs(runtime.LastData) do
                        if shouldShow(data) and updateLabel(data) then
                            seen[data.Key] = true
                        end
                    end
                end

                for key, record in pairs(runtime.Labels) do
                    if not seen[key] then
                        if record.Billboard and record.Billboard.Parent then
                            record.Billboard:Destroy()
                        end
                        runtime.Labels[key] = nil
                    end
                end
            end

            local function need(parent, name, timeout)
                local object = parent and parent:WaitForChild(name, timeout or 10)
                if not object then
                    error("Missing " .. tostring(name))
                end
                return object
            end

            local function normalize(value)
                return tostring(value or ""):lower():gsub("[^%w]", "")
            end

            local function ensureModules()
                if runtime.ModulesReady then
                    return true
                end
                if runtime.ModulesFailed then
                    return false
                end

                local ok, err = pcall(function()
                    local sharedModules = need(ReplicatedStorage, "SharedModules", 10)
                    local G = runtime.Modules
                    G.Sell = require(need(sharedModules, "SellValueData", 10))
                    G.MutationData = require(need(sharedModules, "MutationData", 10))
                    G.SeedData = require(need(sharedModules, "SeedData", 10))
                    G.FruitIdentity = require(need(sharedModules, "FruitIdentity", 10))

                    local controllers = need(
                        need(LP, "PlayerScripts", 10),
                        "Controllers",
                        10
                    )
                    G.GardenSync = require(
                        need(controllers, "GardenSyncController", 10)
                    )

                    local generation = need(ReplicatedStorage, "PlantGenerationModules", 10)
                    G.FruitModules = need(generation, "Fruits", 10)
                    G.PlantModules = need(generation, "Plants", 10)

                    clearSet(runtime.SellNorm)
                    for key in pairs(G.Sell) do
                        runtime.SellNorm[normalize(key)] = key
                    end

                    clearSet(runtime.SingleHarvest)
                    for _, value in pairs(G.SeedData) do
                        if type(value) == "table" and value.SeedName then
                            runtime.SingleHarvest[value.SeedName] = value.IsSingleHarvest == true
                        end
                    end
                end)

                if not ok then
                    runtime.ModulesFailed = true
                    warn("[ScoopHub Garden ESP] Required modules unavailable: " .. tostring(err))
                    return false
                end

                runtime.ModulesReady = true
                return true
            end

            local function getOwnPlot()
                local gardens = Workspace:FindFirstChild("Gardens")
                if not gardens then
                    return nil
                end

                local plotId = LP:GetAttribute("PlotId")
                if plotId ~= nil then
                    local direct = gardens:FindFirstChild("Plot" .. tostring(plotId))
                    if direct then
                        return direct
                    end
                end

                for _, plot in ipairs(gardens:GetChildren()) do
                    if plot:GetAttribute("OwnerUserId") == LP.UserId
                        or plot:GetAttribute("Owner") == LP.Name then
                        return plot
                    end
                end
                return nil
            end

            local function resolveFruit(seed)
                if not seed then
                    return nil
                end
                if runtime.ResolveCache[seed] ~= nil then
                    return runtime.ResolveCache[seed]
                end

                local G = runtime.Modules
                local ok, value = pcall(function()
                    return G.FruitIdentity.ResolveFruitName(seed)
                end)
                value = ok and value or seed
                runtime.ResolveCache[seed] = value
                return value
            end

            local function isMulti(seed)
                if runtime.MultiCache[seed] ~= nil then
                    return runtime.MultiCache[seed]
                end
                local resolved = resolveFruit(seed)
                local G = runtime.Modules
                local value = resolved ~= nil
                    and G.FruitModules:FindFirstChild(resolved) ~= nil
                    or false
                runtime.MultiCache[seed] = value
                return value
            end

            local function getModuleData(folder, name)
                if not name then
                    return nil
                end

                local key = folder:GetFullName() .. "|" .. tostring(name)
                if runtime.ModuleCache[key] ~= nil then
                    return runtime.ModuleCache[key] or nil
                end

                local module = folder:FindFirstChild(name)
                if not module then
                    local wanted = normalize(name)
                    for _, candidate in ipairs(folder:GetChildren()) do
                        if candidate:IsA("ModuleScript")
                            and normalize(candidate.Name) == wanted then
                            module = candidate
                            break
                        end
                    end
                end

                if not module or not module:IsA("ModuleScript") then
                    runtime.ModuleCache[key] = false
                    return nil
                end

                local ok, data = pcall(require, module)
                if not ok or type(data) ~= "table" then
                    runtime.ModuleCache[key] = false
                    return nil
                end

                runtime.ModuleCache[key] = data
                return data
            end

            local function baseWeight(folder, name)
                local data = getModuleData(folder, name)
                return data
                    and data.GrowData
                    and tonumber(data.GrowData.BaseWeight)
                    or nil
            end

            local function mutationMultiplier(name)
                if not name or name == "" then
                    return 1
                end
                if runtime.MutationCache[name] ~= nil then
                    return runtime.MutationCache[name]
                end

                local ok, value = pcall(function()
                    return runtime.Modules.MutationData.ReturnPriceMultiplier(name)
                end)
                value = ok and tonumber(value) or 1
                runtime.MutationCache[name] = value
                return value
            end

            local function sellKey(...)
                local names = {...}
                local G = runtime.Modules

                for _, name in ipairs(names) do
                    if name and G.Sell[name] ~= nil then
                        return name
                    end
                end

                for _, name in ipairs(names) do
                    if name then
                        local found = runtime.SellNorm[normalize(name)]
                        if found then
                            return found
                        end
                    end
                end

                return names[1]
            end

            local function calculateValue(name, size, mutation, decayAlpha)
                if not name then
                    return 0
                end

                local base = tonumber(runtime.Modules.Sell[name]) or 0
                size = tonumber(size) or 1

                local exponent = 2.5
                if name == "Mushroom" then
                    exponent = 1.9
                elseif name == "Bamboo" then
                    exponent = 1.75
                end

                local sizeValue = size ^ exponent
                local knee = 5
                local tailExponent = 1.5
                if size > knee then
                    sizeValue = knee ^ exponent
                        * (size / knee) ^ math.min(tailExponent, exponent)
                end

                local mutationValue = 1
                if mutation and mutation ~= "" then
                    mutationValue = mutationMultiplier(mutation)
                    if runtime.SingleHarvest[name] and mutationValue > 1 then
                        mutationValue = 1 + (mutationValue - 1) * 0.15
                    end
                end

                local decayMultiplier = 1
                if type(decayAlpha) == "number" and decayAlpha > 0 then
                    decayMultiplier = 1 - math.clamp(decayAlpha, 0, 1) * 0.8
                end

                local friends = tonumber(LP:GetAttribute("Friends")) or 0
                local friendMultiplier = 1 + friends * 0.1

                local value = math.floor(
                    base
                    * sizeValue
                    * mutationValue
                    * decayMultiplier
                    * friendMultiplier
                )

                if name == "Carrot" then
                    value = math.max(value, 4)
                end
                return value
            end

            local function resetSyncCache()
                clearSet(runtime.SyncCache)
            end

            local function syncedPlant(plant)
                local cached = runtime.SyncCache[plant]
                if cached ~= nil then
                    return cached ~= false and cached or nil
                end

                local plantId = plant:GetAttribute("PlantId")
                if not plantId then
                    runtime.SyncCache[plant] = false
                    return nil
                end

                local userId = tonumber(plant:GetAttribute("UserId")) or LP.UserId
                local ok, data = pcall(function()
                    return runtime.Modules.GardenSync:GetPlant(userId, plantId)
                end)

                if not ok or type(data) ~= "table" then
                    runtime.SyncCache[plant] = false
                    return nil
                end

                runtime.SyncCache[plant] = data
                return data
            end

            local function syncedFruit(plantData, fruit)
                if not plantData or type(plantData.Fruits) ~= "table" then
                    return nil
                end
                local fruitId = fruit:GetAttribute("FruitId")
                if fruitId == nil then
                    return nil
                end
                return plantData.Fruits[fruitId]
                    or plantData.Fruits[tostring(fruitId)]
            end

            local function atlanticGrowth(seconds)
                seconds = math.max(tonumber(seconds) or 0, 0)
                if seconds <= 0 then
                    return 1
                end
                return math.min(
                    1 + 0.0128 * (math.log(1 + seconds / 1800) ^ 2.55),
                    25
                )
            end

            local function makeMultiData(plant, fruit, plantData, serverNow)
                local seed = plant:GetAttribute("SeedName")
                local resolved = resolveFruit(seed)
                local core = fruit:GetAttribute("CorePartName") or resolved
                local synced = syncedFruit(plantData, fruit)

                local size = tonumber(fruit:GetAttribute("SizeMulti"))
                    or tonumber(synced and synced.SizeMultiplier)
                    or tonumber(fruit:GetAttribute("SizeMultiplier"))
                    or 1

                local overtime = tonumber(synced and synced.OvertimeGrowth)
                    or tonumber(fruit:GetAttribute("OvertimeGrowth"))
                    or 1
                overtime = math.max(overtime, 1)

                local atlantic = normalize(resolved) == "atlanticgiantpumpkin"
                    or normalize(core) == "atlanticgiantpumpkin"
                    or normalize(seed) == "atlanticgiantpumpkin"

                if atlantic then
                    local finished = tonumber(synced and synced.FinishedGrowingAt)
                        or tonumber(fruit:GetAttribute("FinishedGrowingAt"))
                    if finished and finished > 0 then
                        overtime = atlanticGrowth(math.max(serverNow - finished, 0))
                    end
                end

                local weightBase = baseWeight(runtime.Modules.FruitModules, core)
                if not weightBase and resolved then
                    weightBase = baseWeight(runtime.Modules.FruitModules, resolved)
                end
                weightBase = weightBase or 0

                local mutation = (synced and synced.Mutation)
                    or fruit:GetAttribute("Mutation")
                if mutation == "" then
                    mutation = nil
                end

                local valueName = sellKey(core, resolved, seed)
                local decay = (synced and synced.DecayAlpha)
                    or fruit:GetAttribute("DecayAlpha")

                return {
                    Key = "M|"
                        .. tostring(plant:GetAttribute("PlantId"))
                        .. "|"
                        .. tostring(fruit:GetAttribute("FruitId")),
                    Name = seed or resolved or core or fruit.Name,
                    Mutation = mutation or "Normal",
                    KG = weightBase * size * overtime,
                    Value = calculateValue(valueName, size, mutation, decay),
                    Object = fruit,
                }
            end

            local function makeSingleData(plant, plantData)
                if not plantData then
                    return nil
                end

                local seed = plant:GetAttribute("SeedName")
                local resolved = resolveFruit(seed)
                local size = tonumber(plantData.SizeMultiplier) or 1
                local overtime = math.max(tonumber(plantData.OvertimeGrowth) or 1, 1)
                local weightBase = baseWeight(runtime.Modules.PlantModules, seed)
                    or baseWeight(runtime.Modules.PlantModules, plantData.PlantName)
                    or 0
                local weight = tonumber(plantData.Weight)
                    or weightBase * size * overtime
                local mutation = plantData.Mutation
                    or plant:GetAttribute("Mutation")
                if mutation == "" then
                    mutation = nil
                end

                local valueName = sellKey(resolved, seed, plantData.PlantName)
                local decay = plantData.DecayAlpha
                    or plant:GetAttribute("DecayAlpha")

                return {
                    Key = "S|" .. tostring(plant:GetAttribute("PlantId")),
                    Name = seed or plantData.PlantName or plant.Name,
                    Mutation = mutation or "Normal",
                    KG = weight,
                    Value = calculateValue(valueName, size, mutation, decay),
                    Object = plant,
                }
            end

            local function scanGarden()
                if not ensureModules() then
                    return {}
                end

                resetSyncCache()
                local output = {}
                local plot = getOwnPlot()
                local plants = plot and plot:FindFirstChild("Plants")
                if not plants then
                    return output
                end

                local serverNow = Workspace:GetServerTimeNow()
                local sliceStart = os.clock()

                local function yieldIfNeeded()
                    if os.clock() - sliceStart >= 0.0025 then
                        task.wait()
                        sliceStart = os.clock()
                    end
                end

                for _, plant in ipairs(plants:GetChildren()) do
                    if not runtime.Enabled or not ScoopHubRunAlive() then
                        break
                    end

                    local seed = plant:GetAttribute("SeedName")
                    if seed then
                        runtime.KnownFruits[tostring(seed)] = true

                        -- Do not calculate GardenSync/value data for fruit types the
                        -- user did not select. This keeps ESP cheap in huge gardens.
                        if not fruitSelectionMatches(seed) then
                            continue
                        end

                        local plantData = syncedPlant(plant)

                        if isMulti(seed) then
                            local fruits = plant:FindFirstChild("Fruits")
                            if fruits then
                                for _, fruit in ipairs(fruits:GetChildren()) do
                                    if fruit:GetAttribute("FruitId") ~= nil then
                                        local ok, data = pcall(
                                            makeMultiData,
                                            plant,
                                            fruit,
                                            plantData,
                                            serverNow
                                        )
                                        if ok and data then
                                            runtime.KnownMutations[data.Mutation] = true
                                            output[#output + 1] = data
                                        end
                                        yieldIfNeeded()
                                    end
                                end
                            end
                        else
                            local ok, data = pcall(makeSingleData, plant, plantData)
                            if ok and data then
                                runtime.KnownMutations[data.Mutation] = true
                                output[#output + 1] = data
                            end
                            yieldIfNeeded()
                        end
                    end
                end

                return output
            end

            local function refreshNow()
                if not runtime.Enabled or not hasUsableSelection() then
                    applyData({})
                    return
                end

                local ok, result = pcall(scanGarden)
                if not ok then
                    warn("[ScoopHub Garden ESP] Scan failed: " .. tostring(result))
                    return
                end
                applyData(result)
            end

            local function restartWorker()
                runtime.WorkerGeneration += 1
                local generation = runtime.WorkerGeneration

                if not runtime.Enabled or not hasUsableSelection() then
                    applyData({})
                    return
                end

                task.spawn(function()
                    while runtime.Enabled
                        and runtime.WorkerGeneration == generation
                        and ScoopHubRunAlive()
                        and SG.Parent do
                        refreshNow()
                        task.wait(2)
                    end
                end)
            end

            -- ------------------------- UI -------------------------------------
            -- Automation-style Garden ESP card.
            -- It still occupies ONLY ONE Misc column; the extra height is vertical.
            local GardenEspCard = card(
                1,
                7,
                "GARDEN ESP",
                ""
            )
            GardenEspCard.Size = UDim2.new(.5, -3, 0, GARDEN_ESP_CARD_H)

            local function makeSelector(fieldTitle, y, initialText)
                -- Match Automation createFieldButton + compact multi-select exactly.
                label(
                    GardenEspCard,
                    fieldTitle,
                    UDim2.new(0, 10, 0, y),
                    UDim2.new(1, -20, 0, 14),
                    10,
                    T.Muted,
                    T.Font
                )

                local buttonObject = C(N("TextButton", {
                    Text = "",
                    Font = T.Body,
                    TextSize = 11,
                    TextColor3 = T.White,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    BackgroundColor3 = T.Input,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    Position = UDim2.new(0, 10, 0, y + 17),
                    Size = UDim2.new(1, -20, 0, 27),
                    ClipsDescendants = true,
                    ZIndex = 5,
                }, GardenEspCard), 5)

                S(buttonObject, T.Stroke, .82, 1)

                local selectorText = N("TextLabel", {
                    Name = "CompactSelectorText",
                    Text = initialText,
                    Font = T.Body,
                    TextSize = 12,
                    TextColor3 = T.White,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    BackgroundTransparency = 1,
                    Position = UDim2.new(0, 8, 0, 0),
                    Size = UDim2.new(1, -28, 1, 0),
                    ZIndex = 6,
                }, buttonObject)

                local chevron = N("Frame", {
                    Name = "CompactSelectorChevron",
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    Position = UDim2.new(1, -20, 0.5, -5),
                    Size = UDim2.fromOffset(14, 10),
                    Rotation = 0,
                    ZIndex = 6,
                }, buttonObject)

                N("Frame", {
                    Name = "ChevronLeft",
                    BackgroundColor3 = T.Muted,
                    BorderSizePixel = 0,
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, -2, 0.5, 0),
                    Size = UDim2.fromOffset(7, 2),
                    Rotation = 45,
                    ZIndex = 7,
                }, chevron)

                N("Frame", {
                    Name = "ChevronRight",
                    BackgroundColor3 = T.Muted,
                    BorderSizePixel = 0,
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, 2, 0.5, 0),
                    Size = UDim2.fromOffset(7, 2),
                    Rotation = -45,
                    ZIndex = 7,
                }, chevron)

                return buttonObject, selectorText, chevron
            end

            local FruitSelector, FruitSelectorText, FruitChevron = makeSelector(
                "FRUITS TO SHOW",
                27,
                "None selected"
            )

            local MutationSelector, MutationSelectorText, MutationChevron = makeSelector(
                "MUTATIONS TO SHOW",
                78,
                "All mutations"
            )

            -- Match Automation createToggle exactly: title/subtitle on the left,
            -- 48x23 pill on the right, directly inside the card.
            local GardenEspToggleState = false

            label(
                GardenEspCard,
                "GARDEN ESP",
                UDim2.new(0, 10, 0, 132),
                UDim2.new(1, -82, 0, 14),
                11,
                T.White,
                T.Font
            )

            label(
                GardenEspCard,
                "Show selected fruits",
                UDim2.new(0, 10, 0, 146),
                UDim2.new(1, -82, 0, 13),
                9,
                T.Muted,
                T.Body
            )

            local GardenEspToggleButton = C(N("TextButton", {
                Text = "",
                BackgroundColor3 = T.RedDark,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Position = UDim2.new(1, -58, 0, 134),
                Size = UDim2.fromOffset(48, 23),
                ZIndex = 5,
            }, GardenEspCard), 12)

            local GardenEspToggleKnob = C(N("Frame", {
                BackgroundColor3 = T.White,
                BorderSizePixel = 0,
                AnchorPoint = Vector2.new(0, .5),
                Position = UDim2.new(0, 3, .5, 0),
                Size = UDim2.fromOffset(17, 17),
                ZIndex = 6,
            }, GardenEspToggleButton), 10)

            local GardenEspToggle = {}

            function GardenEspToggle:Set(value, fireCallback)
                GardenEspToggleState = value == true

                GardenEspToggleButton.BackgroundColor3 =
                    GardenEspToggleState
                    and T.Success
                    or T.RedDark

                tw(
                    GardenEspToggleKnob,
                    {
                        Position =
                            GardenEspToggleState
                            and UDim2.new(1, -20, .5, 0)
                            or UDim2.new(0, 3, .5, 0)
                    },
                    .15
                )

                if fireCallback ~= false then
                    runtime.Enabled = GardenEspToggleState
                    State.GardenESPEnabled = runtime.Enabled
                    restartWorker()
                end
            end

            function GardenEspToggle:Get()
                return GardenEspToggleState
            end

            TrackConnection(GardenEspToggleButton.Activated:Connect(function()
                GardenEspToggle:Set(not GardenEspToggleState, true)
            end))

            -- Same compact open-dropdown structure as Automation:
            -- search -> SELECT ALL / CLEAR ALL -> scrollable options.
            local Dropdown = C(N("Frame", {
                Name = "GardenESPMultiSelect",
                Visible = false,
                Position = UDim2.fromOffset(0, 0),
                Size = UDim2.fromOffset(230, 240),
                BackgroundColor3 = T.Surface2,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                ZIndex = 500,
            }, Page), 6)
            S(Dropdown, T.Red, 0, 1.5)

            local FilterBox = C(N("TextBox", {
                Position = UDim2.new(0, 4, 0, 4),
                Size = UDim2.new(1, -8, 0, 26),
                BackgroundColor3 = T.Surface3,
                BorderSizePixel = 0,
                Text = "",
                PlaceholderText = "Search...",
                PlaceholderColor3 = T.Muted,
                TextColor3 = T.White,
                Font = T.Body,
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
                ClearTextOnFocus = false,
                ZIndex = 502,
            }, Dropdown), 5)
            N("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
            }, FilterBox)

            local ActionRow = N("Frame", {
                Name = "GardenESPActions",
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Position = UDim2.new(0, 4, 0, 34),
                Size = UDim2.new(1, -8, 0, 26),
                ZIndex = 501,
            }, Dropdown)

            local SelectAllButton = C(N("TextButton", {
                Position = UDim2.new(0, 0, 0, 0),
                Size = UDim2.new(.5, -2, 1, 0),
                BackgroundColor3 = T.RedDark,
                BorderSizePixel = 0,
                Text = "SELECT ALL",
                TextColor3 = T.White,
                Font = T.Font,
                TextSize = 11,
                AutoButtonColor = false,
                ZIndex = 502,
            }, ActionRow), 4)

            local ClearAllButton = C(N("TextButton", {
                Position = UDim2.new(.5, 2, 0, 0),
                Size = UDim2.new(.5, -2, 1, 0),
                BackgroundColor3 = T.Surface3,
                BorderSizePixel = 0,
                Text = "CLEAR ALL",
                TextColor3 = T.White,
                Font = T.Font,
                TextSize = 11,
                AutoButtonColor = false,
                ZIndex = 502,
            }, ActionRow), 4)

            local OptionScroll = N("ScrollingFrame", {
                Position = UDim2.new(0, 4, 0, 64),
                Size = UDim2.new(1, -8, 1, -68),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.new(),
                ScrollBarThickness = 3,
                ScrollBarImageColor3 = T.Red,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                ZIndex = 501,
            }, Dropdown)

            local DropdownMode = nil
            local OptionRows = {}

            local function updateSelectorText()
                local fruitValues = sortedKeys(runtime.SelectedFruits)
                local mutationValues = sortedKeys(runtime.SelectedMutations)
                local fruitCount = #fruitValues
                local mutationCount = #mutationValues

                if runtime.FruitAll then
                    FruitSelectorText.Text = "All fruits"
                elseif fruitCount == 0 then
                    FruitSelectorText.Text = "None selected"
                elseif fruitCount == 1 then
                    FruitSelectorText.Text = fruitValues[1]
                elseif fruitCount == 2 then
                    FruitSelectorText.Text = fruitValues[1] .. ", " .. fruitValues[2]
                else
                    FruitSelectorText.Text = fruitValues[1]
                        .. ", "
                        .. fruitValues[2]
                        .. " +"
                        .. tostring(fruitCount - 2)
                end

                if runtime.MutationAll then
                    MutationSelectorText.Text = "All mutations"
                elseif mutationCount == 0 then
                    MutationSelectorText.Text = "None selected"
                elseif mutationCount == 1 then
                    MutationSelectorText.Text = mutationValues[1]
                elseif mutationCount == 2 then
                    MutationSelectorText.Text = mutationValues[1] .. ", " .. mutationValues[2]
                else
                    MutationSelectorText.Text = mutationValues[1]
                        .. ", "
                        .. mutationValues[2]
                        .. " +"
                        .. tostring(mutationCount - 2)
                end
            end

            local function setSelectorChevron(chevron, open, instant)
                local targetRotation = open and 180 or 0
                if instant then
                    chevron.Rotation = targetRotation
                else
                    tw(chevron, {Rotation = targetRotation}, .14)
                end
            end

            local function setDropdownOpen(opened)
                Dropdown.Visible = opened == true
                setSelectorChevron(
                    FruitChevron,
                    opened and DropdownMode == "Fruit",
                    false
                )
                setSelectorChevron(
                    MutationChevron,
                    opened and DropdownMode == "Mutation",
                    false
                )
            end

            local function clearOptionRows()
                for index = #OptionRows, 1, -1 do
                    local row = OptionRows[index]
                    if row and row.Parent then
                        row:Destroy()
                    end
                    OptionRows[index] = nil
                end
            end

            local function knownOptions()
                local source = DropdownMode == "Fruit"
                    and runtime.KnownFruits
                    or runtime.KnownMutations
                return sortedKeys(source)
            end

            local function isOptionSelected(option)
                if DropdownMode == "Fruit" then
                    return runtime.FruitAll
                        or runtime.SelectedFruits[option] == true
                end
                return runtime.MutationAll
                    or runtime.SelectedMutations[option] == true
            end

            local function materializeAllSelection()
                if DropdownMode == "Fruit" and runtime.FruitAll then
                    clearSet(runtime.SelectedFruits)
                    for option in pairs(runtime.KnownFruits) do
                        runtime.SelectedFruits[option] = true
                    end
                    runtime.FruitAll = false
                elseif DropdownMode == "Mutation" and runtime.MutationAll then
                    clearSet(runtime.SelectedMutations)
                    for option in pairs(runtime.KnownMutations) do
                        runtime.SelectedMutations[option] = true
                    end
                    runtime.MutationAll = false
                end
            end

            local rebuildDropdown
            rebuildDropdown = function()
                if not Dropdown.Visible or not DropdownMode then
                    return
                end

                clearOptionRows()
                local query = string.lower(FilterBox.Text or "")
                local y = 0

                for _, option in ipairs(knownOptions()) do
                    if query == "" or string.find(string.lower(option), query, 1, true) then
                        local selected = isOptionSelected(option)
                        local row = C(N("TextButton", {
                            Position = UDim2.fromOffset(0, y),
                            Size = UDim2.new(1, -4, 0, 27),
                            BackgroundColor3 = selected and T.RedDark or T.Surface2,
                            BackgroundTransparency = selected and .05 or .18,
                            BorderSizePixel = 0,
                            Text = (selected and "✓  " or "   ") .. option,
                            TextColor3 = selected and T.White or T.Muted,
                            Font = selected and T.Font or T.Body,
                            TextSize = 11,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            AutoButtonColor = false,
                            ZIndex = 503,
                        }, OptionScroll), 5)
                        N("UIPadding", {
                            PaddingLeft = UDim.new(0, 8),
                            PaddingRight = UDim.new(0, 8),
                        }, row)

                        TrackConnection(row.Activated:Connect(function()
                            materializeAllSelection()

                            if DropdownMode == "Fruit" then
                                runtime.SelectedFruits[option] =
                                    not runtime.SelectedFruits[option]
                                    or nil
                            else
                                runtime.SelectedMutations[option] =
                                    not runtime.SelectedMutations[option]
                                    or nil
                            end

                            State.GardenESPFruitAll = runtime.FruitAll
                            State.GardenESPMutationAll = runtime.MutationAll
                            State.GardenESPFruits = sortedKeys(runtime.SelectedFruits)
                            State.GardenESPMutations = sortedKeys(runtime.SelectedMutations)

                            updateSelectorText()
                            rebuildDropdown()
                            restartWorker()
                        end))

                        OptionRows[#OptionRows + 1] = row
                        y += 30
                    end
                end

                OptionScroll.CanvasSize = UDim2.new(0, 0, 0, math.max(0, y - 3))
            end

            local function positionDropdown(buttonObject)
                local pagePos = Page.AbsolutePosition
                local pageSize = Page.AbsoluteSize
                local buttonPos = buttonObject.AbsolutePosition
                local buttonSize = buttonObject.AbsoluteSize

                local scaleValue = math.max(tonumber(Scale.Scale) or 1, 0.01)
                local pageWidth = pageSize.X / scaleValue
                local pageHeight = pageSize.Y / scaleValue
                local buttonX = (buttonPos.X - pagePos.X) / scaleValue
                local buttonTop = (buttonPos.Y - pagePos.Y) / scaleValue
                local buttonWidth = buttonSize.X / scaleValue
                local buttonHeight = buttonSize.Y / scaleValue

                -- Automation dropdowns match their selector width.
                local width = math.min(
                    buttonWidth,
                    math.max(0, pageWidth - 8)
                )
                local height = 240

                local x = math.clamp(
                    buttonX,
                    4,
                    math.max(4, pageWidth - width - 4)
                )

                local below = buttonTop + buttonHeight + 4
                local above = buttonTop - height - 4
                local y = below

                if below + height > pageHeight then
                    y = math.max(4, above)
                end

                Dropdown.Position = UDim2.fromOffset(x, y)
                Dropdown.Size = UDim2.fromOffset(width, height)
            end

            local function openDropdown(mode, buttonObject)
                if Dropdown.Visible and DropdownMode == mode then
                    DropdownMode = nil
                    setDropdownOpen(false)
                    return
                end

                DropdownMode = mode
                FilterBox.Text = ""
                FilterBox.PlaceholderText = mode == "Fruit"
                    and "Search fruits..."
                    or "Search mutations..."
                positionDropdown(buttonObject)
                setDropdownOpen(true)
                rebuildDropdown()
            end

            TrackConnection(FruitSelector.Activated:Connect(function()
                openDropdown("Fruit", FruitSelector)
            end))

            TrackConnection(MutationSelector.Activated:Connect(function()
                openDropdown("Mutation", MutationSelector)
            end))

            TrackConnection(FilterBox:GetPropertyChangedSignal("Text"):Connect(function()
                rebuildDropdown()
            end))

            TrackConnection(SelectAllButton.Activated:Connect(function()
                if DropdownMode == "Fruit" then
                    runtime.FruitAll = true
                    clearSet(runtime.SelectedFruits)
                elseif DropdownMode == "Mutation" then
                    runtime.MutationAll = true
                    clearSet(runtime.SelectedMutations)
                end

                State.GardenESPFruitAll = runtime.FruitAll
                State.GardenESPMutationAll = runtime.MutationAll
                State.GardenESPFruits = sortedKeys(runtime.SelectedFruits)
                State.GardenESPMutations = sortedKeys(runtime.SelectedMutations)

                updateSelectorText()
                rebuildDropdown()
                restartWorker()
            end))

            TrackConnection(ClearAllButton.Activated:Connect(function()
                if DropdownMode == "Fruit" then
                    runtime.FruitAll = false
                    clearSet(runtime.SelectedFruits)
                elseif DropdownMode == "Mutation" then
                    runtime.MutationAll = false
                    clearSet(runtime.SelectedMutations)
                end

                State.GardenESPFruitAll = runtime.FruitAll
                State.GardenESPMutationAll = runtime.MutationAll
                State.GardenESPFruits = sortedKeys(runtime.SelectedFruits)
                State.GardenESPMutations = sortedKeys(runtime.SelectedMutations)

                updateSelectorText()
                rebuildDropdown()
                restartWorker()
            end))

            TrackConnection(UIS.InputBegan:Connect(function(input)
                if not Dropdown.Visible then
                    return
                end
                if input.UserInputType ~= Enum.UserInputType.MouseButton1
                    and input.UserInputType ~= Enum.UserInputType.Touch then
                    return
                end

                local point = input.Position
                local function inside(gui)
                    local p = gui.AbsolutePosition
                    local s = gui.AbsoluteSize
                    return point.X >= p.X and point.X <= p.X + s.X
                        and point.Y >= p.Y and point.Y <= p.Y + s.Y
                end

                if not inside(Dropdown)
                    and not inside(FruitSelector)
                    and not inside(MutationSelector) then
                    DropdownMode = nil
                    setDropdownOpen(false)
                end
            end))

            TrackConnection(Page:GetPropertyChangedSignal("Visible"):Connect(function()
                if not Page.Visible then
                    DropdownMode = nil
                    setDropdownOpen(false)
                end
            end))

            TrackConnection(Page:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
                if Dropdown.Visible then
                    local source = DropdownMode == "Fruit"
                        and FruitSelector
                        or MutationSelector
                    if source then
                        positionDropdown(source)
                    end
                end
            end))

            -- Slow distance fallback. BillboardGui.MaxDistance handles this on normal
            -- clients; this keeps behavior consistent where executor/client support is odd.
            task.spawn(function()
                while ScoopHubRunAlive() and SG.Parent do
                    task.wait(.35)
                    if runtime.Enabled then
                        local camera = Workspace.CurrentCamera
                        local cameraPosition = camera and camera.CFrame.Position
                        if cameraPosition then
                            for _, record in pairs(runtime.Labels) do
                                if record.Billboard
                                    and record.Billboard.Parent
                                    and record.Anchor
                                    and record.Anchor.Parent then
                                    record.Billboard.Enabled =
                                        (record.Anchor.Position - cameraPosition).Magnitude <= 135
                                end
                            end
                        end
                    end
                end
            end)

            function feature.GetSettings()
                return {
                    Enabled = runtime.Enabled == true,
                    FruitAll = runtime.FruitAll == true,
                    Fruits = sortedKeys(runtime.SelectedFruits),
                    MutationAll = runtime.MutationAll == true,
                    Mutations = sortedKeys(runtime.SelectedMutations),
                }
            end

            function feature.ApplySettings(data)
                data = type(data) == "table" and data or {}

                runtime.FruitAll = data.FruitAll == true
                runtime.MutationAll = data.MutationAll ~= false
                copyListIntoSet(data.Fruits, runtime.SelectedFruits, runtime.KnownFruits)
                copyListIntoSet(data.Mutations, runtime.SelectedMutations, runtime.KnownMutations)

                -- If a newer config explicitly stores MutationAll=false, respect it.
                if data.MutationAll == false then
                    runtime.MutationAll = false
                end

                State.GardenESPFruitAll = runtime.FruitAll
                State.GardenESPMutationAll = runtime.MutationAll
                State.GardenESPFruits = sortedKeys(runtime.SelectedFruits)
                State.GardenESPMutations = sortedKeys(runtime.SelectedMutations)

                updateSelectorText()
                if Dropdown.Visible then
                    rebuildDropdown()
                end

                GardenEspToggle:Set(data.Enabled == true, true)
                return true
            end

            function feature.SetEnabled(value)
                GardenEspToggle:Set(value == true, true)
            end

            function feature.IsEnabled()
                return runtime.Enabled == true
            end

            function feature.Stop()
                runtime.Enabled = false
                runtime.WorkerGeneration += 1
                destroyLabels()
                if labelFolder and labelFolder.Parent then
                    labelFolder:Destroy()
                end
                labelFolder = nil
                Dropdown.Visible = false
            end

            updateSelectorText()

            RegisterScoopHubCleanup(function()
                feature.Stop()
            end)

            return feature
        end)()

        -- Click outside the FPS dropdown to close it.
        TrackConnection(UIS.InputBegan:Connect(function(input)
            if not FPSDropdown.Visible then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end

            local point = input.Position
            local function inside(gui)
                local p = gui.AbsolutePosition
                local s = gui.AbsoluteSize
                return point.X >= p.X and point.X <= p.X + s.X
                    and point.Y >= p.Y and point.Y <= p.Y + s.Y
            end

            if not inside(FPSDropdown) and not inside(FPSButton) then
                FPSDropdown.Visible = false
            end
        end))

        Page:GetPropertyChangedSignal("Visible"):Connect(function()
            if not Page.Visible then
                FPSDropdown.Visible = false
            end
        end)

        applyMovement()
        applyFPS(State.FPS)

        _G.ScoopHubMiscAPI = {
            GetSettings = function()
                local cleanup = CleanupToggle:Get() == true
                return {
                    AutoRejoin = State.AutoRejoin == true,
                    WalkSpeed = State.WalkSpeed,
                    JumpPower = State.JumpPower,
                    NoClip = State.NoClip == true,
                    InfiniteJump = State.InfiniteJump == true,
                    FPS = tostring(State.FPS),
                    Cleanup = cleanup,
                    RemoveOtherGardens = State.RemoveOtherGardens == true,
                    WildPetESP = WildPetEspToggle:Get() == true,
                    BackpackValueESP = BackpackValueToggle:Get() == true,
                    GardenESP = GardenESPFeature.GetSettings(),
                }
            end,
            ApplySettings = function(data)
                if type(data) ~= "table" then
                    return false
                end

                State.WalkSpeed = math.clamp(tonumber(data.WalkSpeed) or 16, 0, 500)
                State.JumpPower = math.clamp(tonumber(data.JumpPower) or 50, 0, 500)
                WalkBox.Text = tostring(State.WalkSpeed)
                JumpBox.Text = tostring(State.JumpPower)
                applyMovement()

                AutoRejoinToggle:Set(data.AutoRejoin == true, true)
                NoClipToggle:Set(data.NoClip == true, true)
                InfiniteToggle:Set(data.InfiniteJump == true, true)
                CleanupToggle:Set(data.Cleanup == true, true)
                RemoveGardenToggle:Set(data.RemoveOtherGardens == true, true)
                WildPetEspToggle:Set(data.WildPetESP == true, true)
                BackpackValueToggle:Set(data.BackpackValueESP == true, true)
                GardenESPFeature.ApplySettings(data.GardenESP)

                local fpsValue = tostring(data.FPS or "60"):lower()
                local validFPS = false
                for _, option in ipairs(FPSOptions) do
                    if fpsValue == option then
                        validFPS = true
                        break
                    end
                end
                applyFPS(validFPS and fpsValue or "60")
                return true
            end,
            SetAutoRejoin = function(value)
                AutoRejoinToggle:Set(value == true, true)
            end,
            IsAutoRejoinEnabled = function()
                return State.AutoRejoin == true
            end,
            SetCleanup = function(value)
                CleanupToggle:Set(value == true, true)
            end,
            SetRemoveOtherGardens = function(value)
                RemoveGardenToggle:Set(value == true, true)
            end,
            SetBackpackValueESP = function(value)
                BackpackValueToggle:Set(value == true, true)
            end,
            IsBackpackValueESPEnabled = function()
                return BackpackValueToggle:Get() == true
            end,
            SetGardenESP = function(value)
                GardenESPFeature.SetEnabled(value == true)
            end,
            IsGardenESPEnabled = function()
                return GardenESPFeature.IsEnabled()
            end,
            SetFPS = function(value)
                local normalized = tostring(value):lower()
                for _, option in ipairs(FPSOptions) do
                    if normalized == option then
                        applyFPS(option)
                        return true
                    end
                end
                return false
            end,
        }

        print("[ScoopHub] Misc page initialized.")
    end

    __ScoopHubInitMisc()
    local __userInitOk, __userInitErr = pcall(__ScoopHubInitUser)
    if not __userInitOk then
        warn("[ScoopHub] User dashboard init error: " .. tostring(__userInitErr))
    end

    --==================================================
    -- CONFIG PAGE
    --==================================================
    local function __ScoopHubInitConfig()
        local HttpService = game:GetService("HttpService")
        local Page = Configs
        Page.ClipsDescendants = false

        local CONFIG_DIR = "ScoopHub/Configs"
        local META_FILE = CONFIG_DIR .. "/meta_" .. tostring(LP.UserId) .. ".json"
        local currentConfig = ""
        -- Only LOAD CONFIG makes a config active for future rejoin/re-execution.
        -- currentConfig is the chooser/UI selection; activeConfig is what auto-loads.
        local activeConfig = ""
        local knownConfigs = {}
        local autoSave = false
        local lastAutoSaveJSON = nil
        local configBusy = false

        local function ensureFolder()
            if not (isfolder and makefolder) then return false end
            pcall(function()
                if not isfolder("ScoopHub") then makefolder("ScoopHub") end
                if not isfolder(CONFIG_DIR) then makefolder(CONFIG_DIR) end
            end)
            return true
        end

        local function trim(value)
            return tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
        end

        -- Keep config filenames human-readable. Only characters that are unsafe
        -- in normal filenames are replaced, so a config named "My Farm" saves as
        -- ScoopHub/Configs/My Farm.json instead of a hexadecimal filename.
        local function safeFileName(name)
            local value = trim(name)
            value = value:gsub("[%z\1-\31<>:\"/\\|%?%*]", "_")
            value = value:gsub("[%.%s]+$", "")
            if value == "" then value = "Config" end
            return value
        end

        -- Legacy path support for configs saved by the older hex-filename build.
        local function legacyNameKey(name)
            local out = {}
            name = trim(name)
            for i = 1, #name do
                out[#out + 1] = string.format("%02X", string.byte(name, i))
            end
            return table.concat(out)
        end

        local function configPath(name)
            return CONFIG_DIR .. "/" .. safeFileName(name) .. ".json"
        end

        local function legacyConfigPath(name)
            return CONFIG_DIR .. "/config_" .. tostring(LP.UserId) .. "_" .. legacyNameKey(name) .. ".json"
        end

        local function existingConfigPath(name)
            local newPath = configPath(name)
            if isfile then
                local exists = false
                pcall(function() exists = isfile(newPath) end)
                if exists then return newPath end

                local oldPath = legacyConfigPath(name)
                pcall(function() exists = isfile(oldPath) end)
                if exists then return oldPath end
            end
            return newPath
        end

        local function safeClone(value)
            if type(value) ~= "table" then return value end
            local out = {}
            for k, v in pairs(value) do out[k] = safeClone(v) end
            return out
        end

        local function captureConfig(name)
            local data = {
                Version = 3,
                ConfigName = trim(name or currentConfig),
                UserId = LP.UserId,
                SavedAt = os.time(),
                Automation = {},
                Shop = {},
                Misc = {},
            }

            if _G.ScoopHubAutomationAPI and _G.ScoopHubAutomationAPI.GetSettings then
                local ok, value = pcall(_G.ScoopHubAutomationAPI.GetSettings)
                if ok and type(value) == "table" then data.Automation = safeClone(value) end
            end

            if _G.ScoopHubShopAPI and _G.ScoopHubShopAPI.GetSettings then
                local ok, value = pcall(_G.ScoopHubShopAPI.GetSettings)
                if ok and type(value) == "table" then data.Shop = safeClone(value) end
            end

            if _G.ScoopHubMiscAPI and _G.ScoopHubMiscAPI.GetSettings then
                local ok, value = pcall(_G.ScoopHubMiscAPI.GetSettings)
                if ok and type(value) == "table" then data.Misc = safeClone(value) end
            end

            return data
        end

        local function applyConfig(data)
            if type(data) ~= "table" then return false end

            if type(data.Automation) == "table"
                and _G.ScoopHubAutomationAPI
                and _G.ScoopHubAutomationAPI.ApplySettings then
                pcall(_G.ScoopHubAutomationAPI.ApplySettings, data.Automation)
            end

            if type(data.Shop) == "table"
                and _G.ScoopHubShopAPI
                and _G.ScoopHubShopAPI.ApplySettings then
                pcall(_G.ScoopHubShopAPI.ApplySettings, data.Shop)
            end

            if type(data.Misc) == "table"
                and _G.ScoopHubMiscAPI
                and _G.ScoopHubMiscAPI.ApplySettings then
                pcall(_G.ScoopHubMiscAPI.ApplySettings, data.Misc)
            end

            return true
        end

        local function writeJSON(path, data)
            if not (writefile and ensureFolder()) then return false, "writefile unavailable" end
            local ok, encoded = pcall(HttpService.JSONEncode, HttpService, data)
            if not ok then return false, "JSON encode failed" end
            local wrote = pcall(writefile, path, encoded)
            return wrote, wrote and encoded or "write failed"
        end

        local function readJSON(path)
            if not (readfile and isfile) then return nil, "readfile unavailable" end
            local exists = false
            pcall(function() exists = isfile(path) end)
            if not exists then return nil, "config not found" end
            local ok, raw = pcall(readfile, path)
            if not ok or type(raw) ~= "string" or raw == "" then return nil, "read failed" end
            local decodedOk, data = pcall(HttpService.JSONDecode, HttpService, raw)
            if not decodedOk or type(data) ~= "table" then return nil, "invalid JSON" end
            return data, raw
        end

        local function addKnown(name)
            name = trim(name)
            if name == "" then return end
            for _, existing in ipairs(knownConfigs) do
                if string.lower(existing) == string.lower(name) then return end
            end
            table.insert(knownConfigs, name)
            table.sort(knownConfigs, function(a, b) return string.lower(a) < string.lower(b) end)
        end

        local function removeKnown(name)
            for i = #knownConfigs, 1, -1 do
                if string.lower(knownConfigs[i]) == string.lower(name) then
                    table.remove(knownConfigs, i)
                end
            end
        end

        local function loadMeta()
            local meta = readJSON(META_FILE)
            if type(meta) == "table" then
                -- ActiveConfig is deliberately separate from CurrentConfig.
                -- This prevents merely saving/choosing a config from making it
                -- auto-load after a rejoin. Only LOAD CONFIG writes ActiveConfig.
                activeConfig = trim(meta.ActiveConfig)
                currentConfig = activeConfig ~= "" and activeConfig or trim(meta.CurrentConfig)
                autoSave = meta.AutoSave == true
                if type(meta.KnownConfigs) == "table" then
                    for _, name in ipairs(meta.KnownConfigs) do addKnown(name) end
                end
            end
        end

        local function saveMeta()
            writeJSON(META_FILE, {
                CurrentConfig = currentConfig,
                ActiveConfig = activeConfig,
                AutoSave = autoSave,
                KnownConfigs = knownConfigs,
            })
        end

        loadMeta()

