    local minimized=false
    local expandedPosition=Holder.Position
    local miniPosition=nil

    -- Window input is intentionally owned separately from feature/background
    -- connections. This keeps Close/minimize/restore/drag responsive even if a
    -- feature cleanup runs while the current Roblox client is still alive.
    local DisconnectWindowInputs=function() end

    Close.Activated:Connect(function()
        if _G.ScoopHubAutoBuyPetAPI then
