    end)

    -- Minimized launcher icon.
    local MiniLauncher=C(N("TextButton",{
        Name="MiniLauncher",Visible=false,Text="",AutoButtonColor=false,
        AnchorPoint=Vector2.new(.5,.5),Position=Holder.Position,Size=UDim2.fromOffset(48,48),
        BackgroundColor3=T.Bg,BackgroundTransparency=.03,BorderSizePixel=0,ZIndex=500
    },SG),12)
    S(MiniLauncher,T.Red,.35,1)

    N("ImageLabel",{
        Name="MiniLauncherLogo",Image="rbxassetid://90541504618217",BackgroundTransparency=1,
        AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),Size=UDim2.fromOffset(36,36),
        ZIndex=501
    },MiniLauncher)

    local function getMinimizedLauncherPosition()
        -- Put the small launcher exactly where the minimize (-) button was clicked.
        -- This makes the full GUI collapse into the icon instead of making the icon
        -- jump to a different corner of the window.
        local cam=workspace.CurrentCamera
        if not cam then
            return expandedPosition
        end

        local v=cam.ViewportSize
        local half=24

        local buttonPos=Min.AbsolutePosition
        local buttonSize=Min.AbsoluteSize
        local cx=buttonPos.X+(buttonSize.X/2)
        local cy=buttonPos.Y+(buttonSize.Y/2)

        return UDim2.fromOffset(
            math.clamp(cx,half+4,v.X-half-4),
            math.clamp(cy,half+4,v.Y-half-4)
        )
    end

    local function setMinimized(state)
        minimized=state==true

        if minimized then
            -- The big GUI remembers its own position independently from the small
            -- launcher. Reopening always returns to exactly where the big GUI was
            -- when it was minimized.
            expandedPosition=Holder.Position

            -- On the very first minimize, create the launcher at the minimize
            -- button. After that, preserve wherever the user last dragged/clicked
            -- the launcher instead of resetting it to the big GUI.
            if not miniPosition then
                miniPosition=getMinimizedLauncherPosition()
            end

            MiniLauncher.Position=miniPosition
            MiniLauncher.Visible=true
            Body.Visible=false
            Holder.Visible=false
            Min.Text="+"
        else
            -- Save the launcher's independent position before hiding it. Do NOT
            -- move the big GUI to the launcher's position.
            miniPosition=MiniLauncher.Position

            Holder.Position=expandedPosition
            Holder.Visible=true
            Body.Visible=true
            MiniLauncher.Visible=false
            Min.Text="-"
        end
    end

    Min.Activated:Connect(function()
        setMinimized(not minimized)
    end)

    -- Drag + keep window on-screen.
    -- Core window mouse listeners are kept outside TrackConnection so feature/run
    -- cleanup cannot accidentally turn a still-visible ScoopHub window into a dead
    -- GUI. They still disconnect on Close and normal same-server re-execution.
    do
        local draggingHeader=false
        local draggingMini=false
        local miniMoved=false
        local startMouse,startPos
        local activeTouchInput=nil
        local MINI_DRAG_THRESHOLD=6
        local windowInputConnections={}
        local windowInputsDisconnected=false

        local function OwnWindowInput(connection)
            if connection then
                windowInputConnections[#windowInputConnections+1]=connection
            end
            return connection
        end

        DisconnectWindowInputs=function()
            if windowInputsDisconnected then return end
            windowInputsDisconnected=true
            for index=#windowInputConnections,1,-1 do
                local connection=windowInputConnections[index]
                pcall(function() connection:Disconnect() end)
                windowInputConnections[index]=nil
            end
            draggingHeader=false
            draggingMini=false
            activeTouchInput=nil
        end

        Header.InputBegan:Connect(function(i)
            if minimized then return end
            if i.UserInputType==Enum.UserInputType.MouseButton1
                or i.UserInputType==Enum.UserInputType.Touch then
                draggingHeader=true
                draggingMini=false
                activeTouchInput=i.UserInputType==Enum.UserInputType.Touch and i or nil
                startMouse=i.Position
                startPos=Holder.Position
            end
        end)

        MiniLauncher.InputBegan:Connect(function(i)
            if not minimized then return end
            if i.UserInputType==Enum.UserInputType.MouseButton1
                or i.UserInputType==Enum.UserInputType.Touch then
                draggingMini=true
                draggingHeader=false
                miniMoved=false
                activeTouchInput=i.UserInputType==Enum.UserInputType.Touch and i or nil
                startMouse=i.Position
                startPos=MiniLauncher.Position
            end
        end)

        -- Reopening is owned by the launcher button itself instead of depending on
        -- a global InputEnded callback. The drag threshold still prevents a drag
        -- release from being treated as a click.
        MiniLauncher.Activated:Connect(function()
            if minimized and not miniMoved then
                setMinimized(false)
            end
        end)

        OwnWindowInput(UIS.InputEnded:Connect(function(i)
            local endedMouse=i.UserInputType==Enum.UserInputType.MouseButton1
            local endedTouch=i.UserInputType==Enum.UserInputType.Touch and i==activeTouchInput
            if not endedMouse and not endedTouch then return end

            draggingMini=false
            draggingHeader=false
            activeTouchInput=nil
        end))

        OwnWindowInput(UIS.InputChanged:Connect(function(i)
            local movingMouse=i.UserInputType==Enum.UserInputType.MouseMovement and activeTouchInput==nil
            local movingTouch=i.UserInputType==Enum.UserInputType.Touch and i==activeTouchInput
            if not movingMouse and not movingTouch then return end
            if not draggingHeader and not draggingMini then return end

            local d=i.Position-startMouse
            local cam=workspace.CurrentCamera
            if not cam then return end

            local v=cam.ViewportSize
            local baseX=v.X*startPos.X.Scale+startPos.X.Offset+d.X
            local baseY=v.Y*startPos.Y.Scale+startPos.Y.Offset+d.Y

            if draggingMini then
                if d.Magnitude>=MINI_DRAG_THRESHOLD then
                    miniMoved=true
                end

                local half=24
                local px=math.clamp(baseX,half+4,v.X-half-4)
                local py=math.clamp(baseY,half+4,v.Y-half-4)
                MiniLauncher.Position=UDim2.fromOffset(px,py)
                miniPosition=MiniLauncher.Position
                -- The big GUI position is intentionally untouched while the small
                -- launcher is dragged; both positions are stored independently.
            else
                local sw,sh=W*Scale.Scale,H*Scale.Scale
                local px=math.clamp(baseX,sw/2+4,v.X-sw/2-4)
                local py=math.clamp(baseY,sh/2+4,v.Y-sh/2-4)
                Holder.Position=UDim2.fromOffset(px,py)
            end
        end))

        RegisterScoopHubCleanup(function(reason)
            -- A server-hop request must not kill the controls before Roblox actually
            -- leaves the current server. Re-execution/normal cleanup still releases
            -- these global UserInputService connections.
            if reason~="server_hop" then
                DisconnectWindowInputs()
            end
        end)
    end

    --==================================================
    -- GLOBAL SIDEBAR SEARCH
    -- Search tabs/features across ScoopHub, then jump directly to the matching
    -- page/card. Results are indexed once from the finished GUI tree so typing
    -- does not repeatedly scan thousands of descendants.
    --==================================================
    do
        local SearchBox = C(N("TextBox", {
            Name = "ScoopHubGlobalSearch",
            Position = UDim2.fromOffset(6, 7),
            Size = UDim2.new(1, -12, 0, 29),
