        }, Body), 6)
        S(Results, T.Line, .22, 1.2)

        local ResultsScroll = N("ScrollingFrame", {
            Name = "ResultsScroll",
            Position = UDim2.fromOffset(4, 4),
            Size = UDim2.new(1, -8, 1, -8),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            ScrollBarThickness = 3,
            ScrollBarImageColor3 = T.Red,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 1001,
        }, Results)
        local ResultsLayout = N("UIListLayout", {
            Padding = UDim.new(0, 2),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, ResultsScroll)

        local SEARCH_MAX_VISIBLE = 6
        local SEARCH_ROW_HEIGHT = 39
        local SearchIndex = {}
        local SearchRows = {}

        local ignoredExact = {
            ["on"] = true,
            ["off"] = true,
            ["ready"] = true,
            ["enabled"] = true,
            ["disabled"] = true,
            ["select"] = true,
            ["selected"] = true,
            ["search"] = true,
            ["refresh"] = true,
            ["stop"] = true,
            ["start"] = true,
            ["qty"] = true,
            ["owned"] = true,
            ["none"] = true,
            ["all"] = true,
            ["clear"] = true,
            ["save"] = true,
            ["load"] = true,
            ["delete"] = true,
            ["status"] = true,
        }

        local function cleanSearchText(value)
            local result = tostring(value or "")
            result = result:gsub("<[^>]->", "")
            result = result:gsub("^%s+", ""):gsub("%s+$", "")
            result = result:gsub("%s+", " ")
            return result
        end

        local function findPageFor(instance)
            for pageName, pageObject in pairs(Pages) do
                if instance == pageObject or instance:IsDescendantOf(pageObject) then
                    return pageName, pageObject
                end
            end
            return nil, nil
        end

        -- Mail has its own inner navigation (MAIL / MAIL FRUITS / MAIL HISTORY / PENDING).
        -- Preserve that destination in the search index so selecting a result from one
        -- of those inner pages opens the correct Mail sub-tab instead of only opening
        -- the outer Mail page.
        local function findMailSubTab(instance, pageName)
            if pageName ~= "Mail" or not instance then
                return nil
            end

            local byName = {
                MailTab = "mail",
                MailFruitsTab = "fruits",
                MailHistoryTab = "history",
                PendingQueueTab = "pending",
                MailPage = "mail",
                MailFruitsPage = "fruits",
                MailHistoryPage = "history",
                PendingQueuePage = "pending",
            }

            local current = instance
            while current do
                local subTab = byName[current.Name]
                if subTab then
                    return subTab
                end
                if current == Pages[pageName] then
                    break
                end
                current = current.Parent
            end

            return nil
        end

        -- Auto Buy Pet also has inner navigation (DASHBOARD / CONFIGS / HISTORY / WEBHOOK).
        -- Search results must remember which child page owns the matched control so
        -- clicking e.g. PET HISTORY opens Auto Buy Pet directly on HISTORY.
        local function findAutoBuySubTab(instance, pageName)
            if pageName ~= "Auto Buy Pet" or not instance then
                return nil
            end

            local byName = {
                AutoBuyPage = "DASHBOARD",
                SettingsPage = "CONFIGS",
                HistoryPage = "HISTORY",
                WebhookPage = "WEBHOOK",
                DASHBOARDTab = "DASHBOARD",
                CONFIGSTab = "CONFIGS",
                HISTORYTab = "HISTORY",
                WEBHOOKTab = "WEBHOOK",
            }

            local current = instance
            while current do
                local subTab = byName[current.Name]
                if subTab then
                    return subTab
                end
                if current == Pages[pageName] then
                    break
                end
                current = current.Parent
            end

            return nil
        end

        local function isUsefulSearchText(textValue)
            local cleaned = cleanSearchText(textValue)
            local lower = string.lower(cleaned)
            if #cleaned < 3 or #cleaned > 90 then
                return false
            end
            if ignoredExact[lower] then
                return false
            end
            if lower:match("^%d+$") then
                return false
            end
            if lower:match("^[-+x]+$") then
                return false
            end
            return true
        end

        local function findNavigationTarget(instance, pageObject)
            local current = instance
            local bestCard = nil

            while current and current ~= pageObject do
                if current:IsA("GuiObject") and current:IsA("Frame") then
                    local hasCorner = current:FindFirstChildOfClass("UICorner") ~= nil
                    local hasStroke = current:FindFirstChildOfClass("UIStroke") ~= nil
                    local height = current.Size.Y.Offset
                    if (hasCorner or hasStroke) and height >= 35 and height <= 420 then
                        bestCard = current
                        break
                    end
                end
                current = current.Parent
            end

            if bestCard then
                return bestCard
            end

            current = instance
            while current and current.Parent and current.Parent ~= pageObject do
                if current.Parent:IsA("ScrollingFrame") then
                    return current
                end
                current = current.Parent
            end

            return current or instance
        end

        local function buildSearchIndex()
            table.clear(SearchIndex)
            local seen = {}

            -- Tabs are always searchable even if a page has no useful labels yet.
            for pageName, pageObject in pairs(Pages) do
                local key = "tab\31" .. string.lower(pageName)
                seen[key] = true
                SearchIndex[#SearchIndex + 1] = {
                    Name = pageName,
                    Page = pageName,
                    Target = pageObject,
                    Haystack = string.lower(pageName .. " tab"),
                    IsTab = true,
                }
            end

            for _, pageObject in pairs(Pages) do
                for _, instance in ipairs(pageObject:GetDescendants()) do
                    if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
                        local textValue = cleanSearchText(instance.Text)
                        if isUsefulSearchText(textValue) then
                            local pageName, ownerPage = findPageFor(instance)
                            if pageName and ownerPage then
                                local dedupeKey = string.lower(pageName .. "\31" .. textValue)
                                if not seen[dedupeKey] then
                                    seen[dedupeKey] = true
                                    SearchIndex[#SearchIndex + 1] = {
                                        Name = textValue,
                                        Page = pageName,
                                        Target = findNavigationTarget(instance, ownerPage),
                                        Haystack = string.lower(textValue .. " " .. pageName),
                                        IsTab = false,
                                        SubTab = findMailSubTab(instance, pageName),
                                        AutoBuySubTab = findAutoBuySubTab(instance, pageName),
                                    }
                                end
                            end
                        end
                    end
                end
            end
        end

        local function findScrollerFor(target, pageObject)
            local current = target
            while current and current ~= pageObject do
                if current:IsA("ScrollingFrame") then
                    return current
                end
                current = current.Parent
            end
            return nil
        end

        local function highlightSearchTarget(target)
            if not target or not target:IsA("GuiObject") then
                return
            end

            local old = target:FindFirstChild("ScoopHubSearchHighlight")
            if old then old:Destroy() end

            local stroke = N("UIStroke", {
                Name = "ScoopHubSearchHighlight",
                Color = T.Red,
                Thickness = 2,
                Transparency = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            }, target)

            tw(stroke, { Transparency = 0 }, .12)
            task.delay(.42, function()
                if stroke and stroke.Parent then
                    local tween = tw(stroke, { Transparency = 1 }, .28)
                    task.delay(.32, function()
                        if stroke and stroke.Parent then
                            stroke:Destroy()
                        end
                    end)
                end
            end)
        end

        local function jumpToSearchResult(entry)
            if not entry or not Pages[entry.Page] then
                return
            end

            open(entry.Page)

            -- If the result belongs to one of Mail's inner tabs, switch that inner
            -- page before trying to scroll/highlight the destination.
            if entry.Page == "Mail" and entry.SubTab
                and _G.ScoopHubMailAPI and _G.ScoopHubMailAPI.OpenTab then
                pcall(_G.ScoopHubMailAPI.OpenTab, entry.SubTab)
            end

            -- The outer open("Auto Buy Pet") intentionally defaults to DASHBOARD.
            -- Override it here when the search result came from one of Auto Buy Pet's
            -- inner pages so PET HISTORY, CONFIGS, WEBHOOK, etc. land on the right tab.
            if entry.Page == "Auto Buy Pet" and entry.AutoBuySubTab
                and _G.ScoopHubAutoBuyPetAPI and _G.ScoopHubAutoBuyPetAPI.OpenTab then
                pcall(_G.ScoopHubAutoBuyPetAPI.OpenTab, entry.AutoBuySubTab)
            end

            SearchBox.Text = ""
            Results.Visible = false

            task.defer(function()
                task.wait()
                local pageObject = Pages[entry.Page]
                local target = entry.Target
                if not target or not target.Parent then
                    return
                end

                local scroller = findScrollerFor(target, pageObject)
                if scroller then
                    local relativeY = target.AbsolutePosition.Y
                        - scroller.AbsolutePosition.Y
                        + scroller.CanvasPosition.Y
                        - 10
                    local maxY = math.max(0, scroller.AbsoluteCanvasSize.Y - scroller.AbsoluteWindowSize.Y)
                    scroller.CanvasPosition = Vector2.new(
                        scroller.CanvasPosition.X,
                        math.clamp(relativeY, 0, maxY)
                    )
                    task.wait()
                end

                highlightSearchTarget(target)
            end)
        end

        local function scoreSearchEntry(entry, query, tokens)
            local haystack = entry.Haystack
            local nameLower = string.lower(entry.Name)

            if nameLower == query then
                return 0
            end
            if nameLower:sub(1, #query) == query then
                return 1
            end
            if nameLower:find(query, 1, true) then
                return 2
            end
            if haystack:find(query, 1, true) then
                return 3
            end

            for _, token in ipairs(tokens) do
                if not haystack:find(token, 1, true) then
                    return nil
                end
            end
            return 4
        end

        local function clearSearchRows()
            for _, row in ipairs(SearchRows) do
                if row and row.Parent then
                    row:Destroy()
                end
            end
            table.clear(SearchRows)
        end

        local function renderSearchResults(rawQuery)
            clearSearchRows()

            local query = string.lower(cleanSearchText(rawQuery))
            if #query < 2 then
                Results.Visible = false
                return
            end

            local tokens = {}
            for token in query:gmatch("%S+") do
                tokens[#tokens + 1] = token
            end

            local matches = {}
            for _, entry in ipairs(SearchIndex) do
                local score = scoreSearchEntry(entry, query, tokens)
                if score ~= nil then
                    matches[#matches + 1] = { Entry = entry, Score = score }
                end
            end

            table.sort(matches, function(a, b)
                if a.Score ~= b.Score then
                    return a.Score < b.Score
                end
                if a.Entry.IsTab ~= b.Entry.IsTab then
                    return not a.Entry.IsTab
                end
                if a.Entry.Page ~= b.Entry.Page then
                    return a.Entry.Page < b.Entry.Page
                end
                return string.lower(a.Entry.Name) < string.lower(b.Entry.Name)
            end)

            local shown = math.min(#matches, 40)
            for index = 1, shown do
                local entry = matches[index].Entry
                local row = C(N("TextButton", {
                    Name = "SearchResult",
                    Text = "",
                    Size = UDim2.new(1, -2, 0, SEARCH_ROW_HEIGHT),
                    BackgroundColor3 = T.Surface2,
                    BackgroundTransparency = .03,
                    BorderSizePixel = 0,
                    AutoButtonColor = false,
                    LayoutOrder = index,
                    ZIndex = 1002,
                }, ResultsScroll), 5)
                S(row, T.Line, .72, 1)

                local titleLabel = label(
                    row,
                    entry.IsTab and (string.upper(entry.Name) .. " TAB") or entry.Name,
                    UDim2.new(0, 10, 0, 4),
                    UDim2.new(1, -20, 0, 17),
                    10,
                    T.White,
                    T.Font
                )
                titleLabel.TextTruncate = Enum.TextTruncate.AtEnd
                titleLabel.ZIndex = 1003

                local destinationLabel = entry.Page
                if entry.Page == "Mail" and entry.SubTab then
                    local subTabNames = {
                        mail = "Mail",
                        fruits = "Mail Fruits",
                        history = "Mail History",
                        pending = "Pending",
                    }
                    destinationLabel = "Mail > " .. (subTabNames[entry.SubTab] or entry.SubTab)
                elseif entry.Page == "Auto Buy Pet" and entry.AutoBuySubTab then
                    local subTabNames = {
                        DASHBOARD = "Dashboard",
                        CONFIGS = "Configs",
                        HISTORY = "History",
                        WEBHOOK = "Webhook",
                    }
                    destinationLabel = "Auto Buy Pet > "
                        .. (subTabNames[entry.AutoBuySubTab] or entry.AutoBuySubTab)
                end

                local pageLabel = label(
                    row,
                    entry.IsTab and "Open tab" or destinationLabel,
                    UDim2.new(0, 10, 0, 21),
                    UDim2.new(1, -20, 0, 13),
                    9,
                    T.Muted,
                    T.Body
                )
                pageLabel.ZIndex = 1003

                TrackConnection(row.MouseEnter:Connect(function()
                    tw(row, { BackgroundColor3 = AccentSelectedBg() }, .08)
                end))
                TrackConnection(row.MouseLeave:Connect(function()
                    tw(row, { BackgroundColor3 = T.Surface2 }, .08)
                end))
                TrackConnection(row.Activated:Connect(function()
                    jumpToSearchResult(entry)
                end))

                SearchRows[#SearchRows + 1] = row
            end

            if shown == 0 then
                local empty = C(N("Frame", {
                    Name = "SearchEmpty",
                    Size = UDim2.new(1, -2, 0, SEARCH_ROW_HEIGHT),
                    BackgroundColor3 = T.Surface2,
                    BackgroundTransparency = .08,
                    BorderSizePixel = 0,
                    LayoutOrder = 1,
                    ZIndex = 1002,
                }, ResultsScroll), 5)
                local emptyLabel = label(
                    empty,
                    "No results for \"" .. cleanSearchText(rawQuery) .. "\"",
                    UDim2.new(0, 10, 0, 0),
                    UDim2.new(1, -20, 1, 0),
                    9,
                    T.Muted,
                    T.Body
                )
                emptyLabel.TextTruncate = Enum.TextTruncate.AtEnd
                emptyLabel.ZIndex = 1003
                SearchRows[#SearchRows + 1] = empty
                shown = 1
            end

            local visibleRows = math.min(shown, SEARCH_MAX_VISIBLE)
            local totalHeight = shown * (SEARCH_ROW_HEIGHT + 2)
            Results.Size = UDim2.fromOffset(258, visibleRows * (SEARCH_ROW_HEIGHT + 2) + 8)
            ResultsScroll.CanvasSize = UDim2.new(0, 0, 0, totalHeight)
            ResultsScroll.CanvasPosition = Vector2.new(0, 0)
            Results.Visible = true
        end

        local function pointInsideSearch(gui, point)
            if not gui or not gui.Visible then return false end
            local pos = gui.AbsolutePosition
            local size = gui.AbsoluteSize
            return point.X >= pos.X
                and point.X <= pos.X + size.X
                and point.Y >= pos.Y
                and point.Y <= pos.Y + size.Y
        end

        buildSearchIndex()

        TrackConnection(SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
            renderSearchResults(SearchBox.Text)
        end))

        TrackConnection(SearchBox.Focused:Connect(function()
            if #cleanSearchText(SearchBox.Text) >= 2 then
                renderSearchResults(SearchBox.Text)
            end
        end))

        TrackConnection(UIS.InputBegan:Connect(function(input)
            local isPointer = input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
            if not isPointer or not Results.Visible then
                return
            end

            local point = input.Position
            if not pointInsideSearch(SearchBox, point)
                and not pointInsideSearch(Results, point) then
                Results.Visible = false
            end
        end))

        RegisterScoopHubCleanup(function()
            clearSearchRows()
            if Results and Results.Parent then Results:Destroy() end
            if SearchBox and SearchBox.Parent then SearchBox:Destroy() end
        end)
    end

    --==================================================
    -- API
    --==================================================

    local API={}

    function API:SetStat(k,v) end
    function API:SetTargets(v) end
    function API:SetAutoBuyEnabled(v) if _G.ScoopHubAutoBuyPetAPI then _G.ScoopHubAutoBuyPetAPI.SetEnabled(v) end end
    function API:ForceAutoBuyHop() if _G.ScoopHubAutoBuyPetAPI then _G.ScoopHubAutoBuyPetAPI.ForceHop() end end
    function API:OpenPage(v) open(v) end
    function API:SetSelectedMailItem(v) end
    function API:OpenMailTab(v) if _G.ScoopHubMailAPI then _G.ScoopHubMailAPI.OpenTab(v) end end
    function API:RefreshMail() if _G.ScoopHubMailAPI then _G.ScoopHubMailAPI.Refresh() end end

    (typeof(getgenv)=="function" and getgenv() or _G).ScoopHubUI=API

    open("User")
    print("[ScoopHub] PREMIUM V2")

